const gulfSouthItineraries=[{"id":"new-orleans-la-city","title":"New Orleans, LA: Three-Day Family Adventure","destination":"New Orleans, LA","state":"LA","stateName":"Louisiana","region":"Greater New Orleans","days":3,"tripType":"family adventure","interests":["family","food","historical-sites","scenic"],"budget":1050,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Jazz, beignets, and big history — the Crescent City is made for family wandering.","overview":"New Orleans packs more family-friendly wonder per square mile than almost any American city: a world-class WWII museum, a lush zoo, streetcars that double as rides, and the sensory parade of the French Quarter. Kids love the riverboat, the street performers, and the sheer weirdness of it all — and grownups get the food and music. Plan two full days of attractions plus a slow day to soak up the Quarter. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Ride the St. Charles streetcar — it doubles as a cheap sightseeing tour","The National WWII Museum's 4D experience wows even antsy kids","Morning beignets at Café du Monde beat any theme-park breakfast","A steamboat cruise on the Mississippi feels like time travel","Audubon Zoo's Louisiana Swamp exhibit is pure Bayou magic"],"bestSeason":"February–May; October–November","familyFriendly":"Best for ages 5+. The French Quarter is very walkable but stay on the main streets after dark; museums and the zoo are stroller-friendly.","lat":29.9537,"lng":-90.07775,"itinerary":[{"day":1,"title":"The French Quarter & the River","morning":{"stop":"French Quarter","description":"Start at Jackson Square, where street performers and artists surround the cathedral. Duck into Café du Monde for beignets and hot chocolate — the powdered sugar alone is an attraction for kids. Wander Royal Street's galleries and the French Market for souvenirs.","cost":"Free to explore; beignets ~$20 for the family (est.)","time":"9:00 AM – 12:00 PM"},"afternoon":{"stop":"Steamboat Natchez","description":"Board the last authentic steam-powered sternwheeler on the Mississippi for a two-hour harbor cruise. The calliope concert, engine-room tour, and jazz band keep kids glued to the decks while you learn river history.","cost":"Cruise ~$118 for the family (est.)","time":"2:30 PM – 4:30 PM"},"evening":{"stop":"Mother's Restaurant","description":"Walk to Poydras Street for po'boys piled with the famous 'debris' at this New Orleans institution. Casual, loud, and fast — exactly right after a big first day. Stroll back along the riverfront lights.","cost":"Dinner ~$70 for the family (est.)","time":"6:00 PM – 8:00 PM"}},{"day":2,"title":"History That Moves You","morning":{"stop":"The National WWII Museum","description":"Give the morning to the museum's Louisiana Memorial Pavilion and Campaigns of Courage. The interactive dog-tag stations let each kid follow a real service member's story through the war — a hook that keeps them reading every panel.","cost":"Admission ~$124 for the family (est.)","time":"9:00 AM – 1:00 PM"},"afternoon":{"stop":"The National WWII Museum","description":"Catch the Beyond All Boundaries 4D show (book tickets ahead — it sells out) and the Road to Berlin exhibits. Teens love the Final Mission submarine experience; little ones gravitate to the restored vehicles.","cost":"4D show ~$28 for the family (est.)","time":"1:30 PM – 4:00 PM"},"evening":{"stop":"Garden District","description":"Ride the St. Charles streetcar ($1.25 each way, est.) past the mansions to the Garden District. Grab dinner at a casual Creole spot and let the kids count the oak trees on Magazine Street.","cost":"Streetcar ~$5 for the family; dinner ~$75 (est.)","time":"5:30 PM – 8:00 PM"}},{"day":3,"title":"Zoo Day & Sweet Goodbyes","morning":{"stop":"Audubon Zoo","description":"Head Uptown to the zoo early, when the animals are most active. Don't miss the Louisiana Swamp boardwalk — white alligators, black bears, and a replica Cajun house — plus the cool Jaguar Jungle and the splash park in warm months.","cost":"Admission ~$120 for the family (est.)","time":"10:00 AM – 2:00 PM"},"afternoon":{"stop":"Audubon Zoo","description":"Finish the reptile house and the Asian Domain, then ride the zoo train. Cool off with sno-balls from the food stands before heading out.","cost":"Snacks ~$25 for the family (est.)","time":"2:00 PM – 4:00 PM"},"evening":{"stop":"Brennan's","description":"Splurge one night at Brennan's on Royal Street — the Bananas Foster, flambéed tableside, is pure dinner theater. Kids remember it forever; order the turtle soup if you're feeling classic.","cost":"Dinner ~$160 for the family (est.)","time":"6:30 PM – 8:30 PM"}}],"attractions":[{"name":"French Quarter","description":"The oldest neighborhood in New Orleans, a walkable grid of wrought-iron balconies, brass bands, and 300-year-old streets. Jackson Square, the French Market, and Royal Street are the family-friendly core — music, art, and snacks at every turn.","officialUrl":"https://www.neworleans.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=French%20Quarter%20New%20Orleans%20LA","price":"$0 — free to explore (est.)","photos":["assets/gulf-south/images/new-orleans-la-city/attr1-1.jpg","assets/gulf-south/images/new-orleans-la-city/attr1-2.jpg","assets/gulf-south/images/new-orleans-la-city/attr1-3.jpg","assets/gulf-south/images/new-orleans-la-city/attr1-4.jpg"]},{"name":"The National WWII Museum","description":"A Smithsonian-affiliated, multi-building museum telling the American WWII story through immersive exhibits, oral histories, and restored aircraft and vehicles. The Campaigns of Courage pavilions and the 4D Beyond All Boundaries film are the highlights.","officialUrl":"https://www.nationalww2museum.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=The%20National%20WWII%20Museum%20New%20Orleans%20LA","price":"$38/adult, $24/child (est.)","photos":["assets/gulf-south/images/new-orleans-la-city/attr2-1.jpg","assets/gulf-south/images/new-orleans-la-city/attr2-2.jpg","assets/gulf-south/images/new-orleans-la-city/attr2-3.jpg","assets/gulf-south/images/new-orleans-la-city/attr2-4.jpg"]},{"name":"Audubon Zoo","description":"A 58-acre zoo in Audubon Park consistently ranked among the country's best, with the Louisiana Swamp, Jaguar Jungle, and a hands-on reptile house. The Cool Zoo splash park (seasonal) is a lifesaver on hot days.","officialUrl":"https://www.audubonnaturecenter.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Audubon%20Zoo%20New%20Orleans%20LA","price":"$35/adult, $25/child (est.)","photos":["assets/gulf-south/images/new-orleans-la-city/attr3-1.jpg","assets/gulf-south/images/new-orleans-la-city/attr3-2.jpg","assets/gulf-south/images/new-orleans-la-city/attr3-3.jpg","assets/gulf-south/images/new-orleans-la-city/attr3-4.jpg"]},{"name":"Steamboat Natchez","description":"One of only two true steam-powered sternwheelers left on the Mississippi, offering narrated harbor jazz cruises from the Toulouse Street Wharf. The working steam engines and calliope are as much the show as the skyline views.","officialUrl":"https://www.steamboatnatchez.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Steamboat%20Natchez%20New%20Orleans%20LA","price":"$39/adult, $19/child (est.)","photos":["assets/gulf-south/images/new-orleans-la-city/attr4-1.jpg","assets/gulf-south/images/new-orleans-la-city/attr4-2.jpg","assets/gulf-south/images/new-orleans-la-city/attr4-3.jpg","assets/gulf-south/images/new-orleans-la-city/attr4-4.jpg"]}],"restaurants":[{"name":"Café du Monde","detail":"The 1862 French Quarter coffee stand where beignets and chicory café au lait are a non-negotiable rite of passage.","price":"$"},{"name":"Mother's Restaurant","detail":"Poydras Street institution serving legendary po'boys piled with slow-roasted debris since 1938.","price":"$$"},{"name":"Brennan's","detail":"Royal Street Creole landmark and birthplace of Bananas Foster — the splurge dinner of the trip.","price":"$$$"}],"rainyDay":["The National WWII Museum — easily a full rainy day on its own","Audubon Aquarium & Insectarium on the riverfront","Louisiana Children's Museum in City Park"],"driveNotes":"Flying into MSY, take the E2 airport bus or a ~25-minute rideshare downtown and skip renting a car — the Quarter, Garden District, and zoo are all reachable by streetcar and bus. If you do drive, use a parking garage near your hotel; street parking in the Quarter is scarce and pricey. Arrive before 10 AM for the easiest museum parking on Magazine Street.","related":["baton-rouge-la-capital","lafayette-la-cajun","natchitoches-la-historic"],"imageAsset":"assets/gulf-south/images/new-orleans-la-city/hero.jpg"},{"id":"baton-rouge-la-capital","title":"Baton Rouge, LA: Two-Day Capital Getaway","destination":"Baton Rouge, LA","state":"LA","stateName":"Louisiana","region":"Capital Region","days":2,"tripType":"weekend getaway","interests":["family","museums","historical-sites","outdoors"],"budget":550,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Castles, battleships, and Cajun country charm — Louisiana's capital punches above its weight.","overview":"Baton Rouge is an easy, affordable weekend: a fairy-tale Old State Capitol that's free to tour, a real WWII destroyer kids can climb aboard, and an open-air museum of Louisiana plantation life. Everything is 15 minutes apart, parking is simple, and the food scene near LSU is a bonus. It's a perfect first 'big city' trip for younger kids. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Louisiana's Old State Capitol looks like a storybook castle — and it's free","Climb the decks and gun turrets of the USS Kidd","LSU Rural Life Museum's costumed demos bring 1800s Louisiana alive","LASM's planetarium shows are a crowd-pleaser for all ages","Sunset views of the Mississippi from the levee top"],"bestSeason":"March–May; October–November","familyFriendly":"Best for ages 5+. All four attractions are stroller-friendly; the USS Kidd has steep ladders below deck, so carry little ones there.","lat":30.44335,"lng":-91.18664,"itinerary":[{"day":1,"title":"Downtown History Day","morning":{"stop":"Louisiana's Old State Capitol","description":"Tour the 1850s Gothic 'castle on the river' — free admission, a stunning stained-glass dome, and exhibits on Louisiana's political past (Huey Long's assassination happened on these very steps). The spiral staircase is a photo magnet for kids.","cost":"Free (est.)","time":"9:00 AM – 11:30 AM"},"afternoon":{"stop":"USS Kidd Veterans Museum","description":"Walk the decks of the USS Kidd, a Fletcher-class WWII destroyer moored on the Mississippi. Kids can aim the guns, ring the bell, and explore the crew quarters; the adjacent museum covers Louisiana veterans' stories.","cost":"Admission ~$48 for the family (est.)","time":"1:00 PM – 4:00 PM"},"evening":{"stop":"The Chimes","description":"Head to Highland Road near LSU for Cajun-Creole classics and one of the state's biggest beer lists. The alligator bites and crawfish étouffée are kid-approved, and the porch is great at golden hour.","cost":"Dinner ~$80 for the family (est.)","time":"5:30 PM – 7:30 PM"}},{"day":2,"title":"Rural Life & Science","morning":{"stop":"LSU Rural Life Museum","description":"Wander 25 acres of historic Louisiana buildings — shotgun houses, a blacksmith shop, a country church — with costumed interpreters demonstrating 1800s crafts. The barnyard animals and wide lawns give kids room to run.","cost":"Admission ~$40 for the family (est.)","time":"9:30 AM – 12:30 PM"},"afternoon":{"stop":"Louisiana Art & Science Museum","description":"Downtown's LASM pairs art galleries with hands-on science exhibits and the Irene W. Pennington Planetarium. Catch a planetarium show, then let the kids loose in the discovery labs before you leave town.","cost":"Admission + planetarium ~$52 for the family (est.)","time":"1:30 PM – 4:00 PM"},"evening":{"stop":"Superior Grill","description":"Finish at this Baton Rouge Tex-Mex institution — sizzling fajitas, strong margaritas (for the grownups), and a lively patio that welcomes noisy families.","cost":"Dinner ~$70 for the family (est.)","time":"5:00 PM – 7:00 PM"}}],"attractions":[{"name":"Louisiana's Old State Capitol","description":"The 1847 Gothic Revival 'castle' that housed Louisiana's legislature, famous for its spiral staircase, stained-glass dome, and the ghost of Huey Long. Now a free museum of Louisiana political history with sweeping river views.","officialUrl":"https://www.louisianastatemuseum.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Louisiana%27s%20Old%20State%20Capitol%20Baton%20Rouge%20LA","price":"$0 — free admission (est.)","photos":["assets/gulf-south/images/baton-rouge-la-capital/attr1-1.jpg","assets/gulf-south/images/baton-rouge-la-capital/attr1-2.jpg","assets/gulf-south/images/baton-rouge-la-capital/attr1-3.jpg","assets/gulf-south/images/baton-rouge-la-capital/attr1-4.jpg"]},{"name":"USS Kidd Veterans Museum","description":"A WWII Fletcher-class destroyer permanently moored on the Mississippi, preserved as a museum ship. Visitors climb from the engine room to the bridge, man the guns, and tour the adjacent veterans museum and P-40 aircraft.","officialUrl":"https://www.usskidd.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=USS%20Kidd%20Baton%20Rouge%20LA","price":"$14/adult, $8/child (est.)","photos":["assets/gulf-south/images/baton-rouge-la-capital/attr2-1.jpg","assets/gulf-south/images/baton-rouge-la-capital/attr2-2.jpg","assets/gulf-south/images/baton-rouge-la-capital/attr2-3.jpg","assets/gulf-south/images/baton-rouge-la-capital/attr2-4.jpg"]},{"name":"LSU Rural Life Museum","description":"An outdoor museum of 19th-century Louisiana life on LSU's Burden campus, with 30+ historic structures including slave cabins, a schoolhouse, and a working blacksmith forge. Seasonal demonstrations and festivals fill the calendar.","officialUrl":"https://www.lsu.edu/rurallife","mapsUrl":"https://www.google.com/maps/search/?api=1&query=LSU%20Rural%20Life%20Museum%20Baton%20Rouge%20LA","price":"$12/adult, $9/child (est.)","photos":["assets/gulf-south/images/baton-rouge-la-capital/attr3-1.jpg","assets/gulf-south/images/baton-rouge-la-capital/attr3-2.jpg","assets/gulf-south/images/baton-rouge-la-capital/attr3-3.jpg","assets/gulf-south/images/baton-rouge-la-capital/attr3-4.jpg"]},{"name":"Louisiana Art & Science Museum","description":"Downtown Baton Rouge's art-and-science combo: rotating art galleries, interactive science exhibits, and the state-of-the-art Irene W. Pennington Planetarium, all in a historic railroad depot on the riverfront.","officialUrl":"https://www.lasm.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Louisiana%20Art%20and%20Science%20Museum%20Baton%20Rouge%20LA","price":"$12/adult, $10/child; planetarium shows extra (est.)","photos":["assets/gulf-south/images/baton-rouge-la-capital/attr4-1.jpg","assets/gulf-south/images/baton-rouge-la-capital/attr4-2.jpg","assets/gulf-south/images/baton-rouge-la-capital/attr4-3.jpg","assets/gulf-south/images/baton-rouge-la-capital/attr4-4.jpg"]}],"restaurants":[{"name":"Parrain's Seafood","detail":"Mid City local favorite for fresh Gulf seafood with a Cajun accent — try the crab cakes.","price":"$$"},{"name":"The Chimes","detail":"LSU-area institution with Cajun-Creole comfort food, a huge beer list, and a buzzing porch.","price":"$"},{"name":"Superior Grill","detail":"Baton Rouge Tex-Mex landmark — fajitas, margaritas, and a patio built for families.","price":"$$"}],"rainyDay":["Louisiana Art & Science Museum + planetarium show","Knock Knock Children's Museum on Dalrymple Drive","LSU Museum of Art at the Shaw Center downtown"],"driveNotes":"Baton Rouge is an easy 80-minute drive from New Orleans via I-10 — pair it with a New Orleans trip or do it as a standalone weekend. Downtown attractions cluster within a few blocks, so park once and walk. The Rural Life Museum is 15 minutes south of downtown on Essen Lane; give yourself extra time on LSU game days when traffic snarls.","related":["new-orleans-la-city","lafayette-la-cajun","natchitoches-la-historic"],"imageAsset":"assets/gulf-south/images/baton-rouge-la-capital/hero.jpg"},{"id":"lafayette-la-cajun","title":"Lafayette, LA: Three-Day Cajun Country Adventure","destination":"Lafayette, LA","state":"LA","stateName":"Louisiana","region":"Acadiana","days":3,"tripType":"family adventure","interests":["family","food","museums","scenic"],"budget":800,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Zydeco mornings, bayou afternoons, and the best eating in Louisiana — bienvenue en Acadiana.","overview":"Lafayette is the beating heart of Cajun Country, where kids can watch blacksmiths and weavers at a recreated 1800s village, tour the factory that makes the world's most famous hot sauce, and dance to zydeco at breakfast. It's a food-first destination that happens to be wonderfully family-friendly — casual, musical, and never rushed. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Vermilionville's costumed artisans make 1800s Cajun life hands-on","The TABASCO factory tour ends with tasting straight from the barrel","Sunday zydeco breakfast at Café des Amis is pure Acadiana","Avery Island's Jungle Gardens: alligators, egrets, and ancient oaks","Po'boys at Olde Tyme Grocery — order at the counter like a local"],"bestSeason":"March–May; October–November","familyFriendly":"Best for ages 4+. Vermilionville and Avery Island are stroller-friendly with shaded paths; live music venues are loud but welcoming to kids.","lat":30.22032,"lng":-92.01705,"itinerary":[{"day":1,"title":"Cajun Village Life","morning":{"stop":"Vermilionville","description":"Spend the morning in this living-history village on the Bayou Vermilion. Costumed artisans demonstrate weaving, woodworking, and open-hearth cooking in authentic 1700s–1800s homes, and the flatboat and trapper's cabin are kid favorites.","cost":"Admission ~$40 for the family (est.)","time":"10:00 AM – 1:00 PM"},"afternoon":{"stop":"Vermilionville","description":"Stay for the afternoon music — weekend performances bring Cajun and zydeco bands to the village stage. Grab a snack from the café and let the kids try the wooden pirogues by the bayou.","cost":"Snacks ~$25 for the family (est.)","time":"1:00 PM – 4:00 PM"},"evening":{"stop":"Prejean's","description":"Dinner at this Lafayette Cajun landmark, with live music many nights and a menu of gumbo, étouffée, and alligator bites. Ask about the turtle cheesecake — it's a thing.","cost":"Dinner ~$85 for the family (est.)","time":"6:00 PM – 8:00 PM"}},{"day":2,"title":"Acadian Heritage & Play","morning":{"stop":"Acadian Cultural Center","description":"This National Park Service center tells the Acadian story — from the 1755 expulsion to Cajun Louisiana — through films, music, and artifacts. The ranger talks are short and engaging, and admission is free.","cost":"Free (est.)","time":"9:30 AM – 11:30 AM"},"afternoon":{"stop":"Children's Museum of Acadiana","description":"Downtown's hands-on museum has a miniature grocery store, a bubble factory, a full-size ambulance to climb through, and a TV studio. Perfect for ages 2–10, and an ideal hot-afternoon escape.","cost":"Admission ~$28 for the family (est.)","time":"1:00 PM – 4:00 PM"},"evening":{"stop":"Olde Tyme Grocery","description":"Join the line at this legendary po'boy counter — the shrimp po'boy fully dressed is the move. Cash moves faster, and the picnic tables out front are pure Lafayette.","cost":"Dinner ~$45 for the family (est.)","time":"5:30 PM – 7:00 PM"}},{"day":3,"title":"TABASCO & Jungle Gardens","morning":{"stop":"TABASCO Factory Tour","description":"Drive 35 minutes to Avery Island for the self-guided factory tour — see the mash barrels, bottling lines, and pepper greenhouses, then taste sauces you can't buy in stores. The country store samples are dangerously good.","cost":"Tour ~$56 for the family (est.)","time":"9:30 AM – 12:00 PM"},"afternoon":{"stop":"Jungle Gardens","description":"Right on Avery Island, these 170 acres of gardens wind past alligator ponds, a Buddha temple, and Bird City, a rookery of snowy egrets. Drive the loop slowly with windows down — kids spot gators from the car.","cost":"Admission ~$40 for the family (est.)","time":"12:30 PM – 3:30 PM"},"evening":{"stop":"Café des Amis","description":"End the trip in Breaux Bridge (20 minutes away) at the famous zydeco breakfast spot — weekend mornings mean live zydeco while you eat. If you're there on a weekday evening, the crawfish dishes still sing.","cost":"Dinner ~$70 for the family (est.)","time":"5:30 PM – 7:30 PM"}}],"attractions":[{"name":"Vermilionville","description":"A 23-acre living-history museum on the Bayou Vermilion recreating an 1800s Cajun-Creole village. Costumed artisans, historic homes, live music, and boat tours make it the single best introduction to Cajun culture.","officialUrl":"https://www.bayouvermiliondistrict.org/vermilionville/","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Vermilionville%20Lafayette%20LA","price":"$12/adult, $8/child (est.)","photos":["assets/gulf-south/images/lafayette-la-cajun/attr1-1.jpg","assets/gulf-south/images/lafayette-la-cajun/attr1-2.jpg","assets/gulf-south/images/lafayette-la-cajun/attr1-3.jpg","assets/gulf-south/images/lafayette-la-cajun/attr1-4.jpg"]},{"name":"Acadian Cultural Center","description":"The National Park Service's Jean Lafitte center devoted to Acadian history, with an excellent orientation film, musical instrument displays, and ranger programs. A quiet, air-conditioned gem that's free to enter.","officialUrl":"https://www.nps.gov/jela","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Acadian%20Cultural%20Center%20Lafayette%20LA","price":"$0 — free admission (est.)","photos":["assets/gulf-south/images/lafayette-la-cajun/attr2-1.jpg","assets/gulf-south/images/lafayette-la-cajun/attr2-2.jpg","assets/gulf-south/images/lafayette-la-cajun/attr2-3.jpg","assets/gulf-south/images/lafayette-la-cajun/attr2-4.jpg"]},{"name":"TABASCO Factory Tour & Avery Island","description":"Tour the factory behind the world's most famous pepper sauce on its private island home, then explore the adjacent Jungle Gardens — 170 acres of live oaks, alligator ponds, and egret rookeries. Factory, gardens, and country store in one stop.","officialUrl":"https://www.tabasco.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=TABASCO%20Factory%20Avery%20Island%20LA","price":"$15.50/adult, $12.50/child (est.)","photos":["assets/gulf-south/images/lafayette-la-cajun/attr3-1.jpg","assets/gulf-south/images/lafayette-la-cajun/attr3-2.jpg","assets/gulf-south/images/lafayette-la-cajun/attr3-3.jpg","assets/gulf-south/images/lafayette-la-cajun/attr3-4.jpg"]},{"name":"Children's Museum of Acadiana","description":"Downtown Lafayette's hands-on museum for ages 2–12, with a bubble factory, kid-size grocery store, ambulance, and construction exhibits. Compact, affordable, and a local favorite for rainy afternoons.","officialUrl":"https://www.childrensmuseumofacadiana.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Children%27s%20Museum%20of%20Acadiana%20Lafayette%20LA","price":"$7/person (est.)","photos":["assets/gulf-south/images/lafayette-la-cajun/attr4-1.jpg","assets/gulf-south/images/lafayette-la-cajun/attr4-2.jpg","assets/gulf-south/images/lafayette-la-cajun/attr4-3.jpg","assets/gulf-south/images/lafayette-la-cajun/attr4-4.jpg"]}],"restaurants":[{"name":"Prejean's","detail":"Iconic Cajun restaurant with live music, gumbo flights, and the famous turtle cheesecake.","price":"$$"},{"name":"Café des Amis","detail":"Breaux Bridge landmark famous for its Saturday zydeco breakfast — dancing encouraged.","price":"$"},{"name":"Olde Tyme Grocery","detail":"No-frills po'boy counter locals swear by — the shrimp po'boy fully dressed is the order.","price":"$"}],"rainyDay":["Children's Museum of Acadiana","Acadian Cultural Center (free, air-conditioned)","Lafayette Science Museum downtown"],"driveNotes":"Lafayette sits on I-10, about 2 hours west of New Orleans and 1 hour from Baton Rouge — an easy add-on to either. You'll want a car here: Vermilionville and the museums are in town, but Avery Island is 35 minutes south and Breaux Bridge 20 minutes east. Festival season (spring) books hotels fast; fall visits get the same weather with fewer crowds.","related":["new-orleans-la-city","baton-rouge-la-capital","lake-charles-la-family"],"imageAsset":"assets/gulf-south/images/lafayette-la-cajun/hero.jpg"},{"id":"natchitoches-la-historic","title":"Natchitoches, LA: Two-Day Historic Escape","destination":"Natchitoches, LA","state":"LA","stateName":"Louisiana","region":"Northwest Louisiana","days":2,"tripType":"weekend getaway","interests":["family","historical-sites","food","scenic"],"budget":450,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"The oldest town in Louisiana, where meat pies and movie history line a brick Main Street.","overview":"Natchitoches (say NAK-uh-tish) is the oldest permanent settlement in the Louisiana Purchase, and it wears its history beautifully: a brick Front Street on the Cane River, Creole plantations a short drive away, and the famous Natchitoches meat pie. Steel Magnolias fans get the film sites; everyone else gets one of the prettiest small towns in the South. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Stroll brick Front Street along the Cane River at golden hour","The famous Natchitoches meat pie at Lasyone's — get one of each","Fort St. Jean Baptiste's palisade fort feels like a movie set","Cane River Creole National Historical Park's Oakland Plantation tour","Christmas lights season (late Nov–early Jan) transforms the town"],"bestSeason":"March–May; October–December","familyFriendly":"Best for ages 5+. Front Street is flat and stroller-friendly; the fort has uneven ground, so wear closed shoes.","lat":31.76101,"lng":-93.08759,"itinerary":[{"day":1,"title":"Front Street & the Fort","morning":{"stop":"Front Street Historic District","description":"Walk the brick-paved main street along the Cane River, browsing Kaffie-Frederick (the state's oldest general store, 1863) and the boutiques. Stop at Lasyone's for the legendary meat pies — one classic, one crawfish — before the lunch rush.","cost":"Lunch ~$40 for the family (est.)","time":"9:30 AM – 12:30 PM"},"afternoon":{"stop":"Fort St. Jean Baptiste","description":"Tour the reconstructed 1716 French fort on Cane River Lake: palisade walls, a chapel, and costumed interpreters demonstrating colonial crafts. Kids love the cannon demos and the trade-shop exhibits.","cost":"Admission ~$16 for the family (est.)","time":"1:30 PM – 4:00 PM"},"evening":{"stop":"The Landing Restaurant & Bar","description":"Dinner on Front Street at this riverfront spot — crab cakes, gumbo, and meat pies in a lively setting. Afterward, walk the riverbank as the string lights come on.","cost":"Dinner ~$80 for the family (est.)","time":"6:00 PM – 8:00 PM"}},{"day":2,"title":"Plantations & Sports Legends","morning":{"stop":"Cane River Creole National Historical Park","description":"Drive 20 minutes to Oakland Plantation for the ranger-led tour of the big house and outbuildings — a frank, fascinating look at Creole plantation life. The grounds are shaded and peaceful; tours run on a schedule, so arrive early.","cost":"Free (est.)","time":"9:30 AM – 12:00 PM"},"afternoon":{"stop":"Louisiana Sports Hall of Fame","description":"Back downtown, this striking modern museum (also housing the Northwest Louisiana History Museum) celebrates Louisiana athletes from the Manning family to Shaq. Interactive exhibits keep kids moving; the history wing covers Cane River culture.","cost":"Admission ~$20 for the family (est.)","time":"1:00 PM – 3:30 PM"},"evening":{"stop":"Mayeaux's Steak & Seafood","description":"One nice dinner out on Front Street — prime steaks and Gulf seafood in a white-tablecloth room that still welcomes kids. The catfish Acadiana is the local favorite.","cost":"Dinner ~$120 for the family (est.)","time":"5:30 PM – 7:30 PM"}}],"attractions":[{"name":"Front Street Historic District","description":"Natchitoches' brick-paved main street along the Cane River, lined with 19th-century storefronts, balconied inns, and the state's oldest general store. The Steel Magnolias film sites are marked along the way.","officialUrl":"https://www.natchitoches.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Front%20Street%20Historic%20District%20Natchitoches%20LA","price":"$0 — free to explore (est.)","photos":["assets/gulf-south/images/natchitoches-la-historic/attr1-1.jpg","assets/gulf-south/images/natchitoches-la-historic/attr1-2.jpg","assets/gulf-south/images/natchitoches-la-historic/attr1-3.jpg","assets/gulf-south/images/natchitoches-la-historic/attr1-4.jpg"]},{"name":"Cane River Creole National Historical Park","description":"A National Park Service site preserving Oakland and Magnolia plantations along the Cane River. Ranger-led tours cover 200+ years of Creole history, from French colonial farms to the families — free and enslaved — who worked them.","officialUrl":"https://www.nps.gov/cari","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Cane%20River%20Creole%20National%20Historical%20Park%20Natchitoches%20LA","price":"$0 — free admission (est.)","photos":["assets/gulf-south/images/natchitoches-la-historic/attr2-1.jpg","assets/gulf-south/images/natchitoches-la-historic/attr2-2.jpg","assets/gulf-south/images/natchitoches-la-historic/attr2-3.jpg","assets/gulf-south/images/natchitoches-la-historic/attr2-4.jpg"]},{"name":"Fort St. Jean Baptiste","description":"A full-scale reconstruction of the 1716 French fort that founded Natchitoches, with palisade walls, barracks, a chapel, and costumed interpreters. Cannon firings and craft demos run on weekends.","officialUrl":"https://www.lastateparks.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Fort%20St%20Jean%20Baptiste%20Natchitoches%20LA","price":"$4/person (est.)","photos":["assets/gulf-south/images/natchitoches-la-historic/attr3-1.jpg","assets/gulf-south/images/natchitoches-la-historic/attr3-2.jpg","assets/gulf-south/images/natchitoches-la-historic/attr3-3.jpg","assets/gulf-south/images/natchitoches-la-historic/attr3-4.jpg"]},{"name":"Louisiana Sports Hall of Fame","description":"A striking riverfront museum honoring Louisiana's sports legends — from Terry Bradshaw to Simone Biles — plus the Northwest Louisiana History Museum's Cane River exhibits. Bold architecture and interactive displays.","officialUrl":"https://www.louisianastatemuseum.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Louisiana%20Sports%20Hall%20of%20Fame%20Natchitoches%20LA","price":"$6/person (est.)","photos":["assets/gulf-south/images/natchitoches-la-historic/attr4-1.jpg","assets/gulf-south/images/natchitoches-la-historic/attr4-2.jpg","assets/gulf-south/images/natchitoches-la-historic/attr4-3.jpg","assets/gulf-south/images/natchitoches-la-historic/attr4-4.jpg"]}],"restaurants":[{"name":"Lasyone's Meat Pie Restaurant","detail":"Home of the famous Natchitoches meat pie since 1967 — golden, flaky, and worth the drive alone.","price":"$"},{"name":"The Landing Restaurant & Bar","detail":"Riverfront Front Street spot for crab cakes, gumbo, and meat pies with Cane River views.","price":"$$"},{"name":"Mayeaux's Steak & Seafood","detail":"Upscale downtown steakhouse and seafood room — the special-occasion dinner pick.","price":"$$$"}],"rainyDay":["Louisiana Sports Hall of Fame & Northwest Louisiana History Museum","Kaffie-Frederick General Store — Louisiana's oldest, full of browsing","Cane River Kitchenware cooking class on Front Street"],"driveNotes":"Natchitoches is on I-49, about 3 hours from Baton Rouge and 1 hour south of Shreveport — an easy weekend drive. Park near Front Street and walk everything downtown; the plantations are a 20-minute drive south on LA-119. If you visit during the famous Christmas Festival of Lights (late November–early January), book lodging months ahead.","related":["baton-rouge-la-capital","lafayette-la-cajun","new-orleans-la-city"],"imageAsset":"assets/gulf-south/images/natchitoches-la-historic/hero.jpg"},{"id":"lake-charles-la-family","title":"Lake Charles, LA: Three-Day Family Lake Escape","destination":"Lake Charles, LA","state":"LA","stateName":"Louisiana","region":"Southwest Louisiana","days":3,"tripType":"family adventure","interests":["family","outdoors","nature","scenic"],"budget":700,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Alligators by day, Mardi Gras museums by afternoon — Southwest Louisiana does family trips right.","overview":"Lake Charles pairs Gulf Coast nature with small-city ease: drive the Creole Nature Trail's alligator-filled marshes, swim and picnic at a pine-forest state park, and let the kids loose in one of Louisiana's best children's museums. It's an affordable, crowd-free alternative to the bigger Louisiana cities — and the Cajun food holds its own. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Spot alligators from the car on the Creole Nature Trail","Swim, fish, and picnic under the pines at Sam Houston Jones State Park","The Children's Museum's water tables and climbing structures","The world's largest Mardi Gras costume collection — try some on","Crawfish étouffée at Steamboat Bill's on the lake"],"bestSeason":"March–May; October–November","familyFriendly":"Best for ages 4+. The Creole Nature Trail is a driving route with boardwalk stops — easy with strollers; bring bug spray in summer.","lat":30.22403,"lng":-93.22011,"itinerary":[{"day":1,"title":"The Creole Nature Trail","morning":{"stop":"Creole Nature Trail","description":"Drive the Alligator Loop of Louisiana's Outback — a 180-mile scenic byway of marshes, beaches, and chenier ridges. Stop at the Blue Goose Trail boardwalk and the Pintail Wildlife Drive; kids count gators from the car windows.","cost":"Free (est.)","time":"9:00 AM – 1:00 PM"},"afternoon":{"stop":"Creole Nature Trail","description":"Continue to Holly Beach for shelling and wading in the Gulf, then the Cameron Ferry (free, runs continuously) for dolphin spotting. Pack a cooler — services are sparse on the loop.","cost":"Free; picnic ~$30 (est.)","time":"1:30 PM – 5:00 PM"},"evening":{"stop":"Steamboat Bill's on the Lake","description":"Back in town, eat on the water at this local landmark — crawfish étouffée, fried alligator bites, and shrimp pistolettes. The sunset over Lake Charles is the dessert.","cost":"Dinner ~$75 for the family (est.)","time":"6:30 PM – 8:00 PM"}},{"day":2,"title":"State Park & Play","morning":{"stop":"Sam Houston Jones State Park","description":"Spend the morning under the longleaf pines: hike the easy Discovery Trail, rent a canoe on the lazy river, and let the kids loose on the playground. The park's 1,000+ acres feel a world away from town.","cost":"Entry ~$12 per vehicle (est.)","time":"9:00 AM – 12:30 PM"},"afternoon":{"stop":"Children's Museum of Southwest Louisiana","description":"Head back to town for the children's museum — water tables, a climbing wall, a kid-size H-E-B-style market, and art studios. A perfect hot-afternoon refuge for ages 2–10.","cost":"Admission ~$32 for the family (est.)","time":"1:30 PM – 4:30 PM"},"evening":{"stop":"Darrell's","description":"Dinner at the Lake Charles po'boy institution — the Darrell's Special with jalapeño mayo is the legend. Cheap, fast, and exactly what tired kids need.","cost":"Dinner ~$45 for the family (est.)","time":"6:00 PM – 7:30 PM"}},{"day":3,"title":"Mardi Gras & the Lakefront","morning":{"stop":"Mardi Gras Museum of Imperial Calcasieu","description":"Tour the world's largest collection of Mardi Gras costumes in the historic 1911 City Hall — towering feathered headdresses, king and queen gowns, and hands-on exhibits. Kids can try on costumes for photos.","cost":"Admission ~$46 for the family (est.)","time":"10:00 AM – 12:00 PM"},"afternoon":{"stop":"Lakefront Promenade","description":"Walk the lakefront boardwalk, splash in the fountains at Millennium Park, and browse the Historic City Hall Arts Center. Rent bikes or just watch the boats on Prien Lake.","cost":"Free (est.)","time":"1:00 PM – 4:00 PM"},"evening":{"stop":"Luna Bar & Grill","description":"Finish downtown at this artsy bar-grill — the Galactic Crab Dip and Redfish Apollo are local favorites, and the patio has live music on weekends.","cost":"Dinner ~$80 for the family (est.)","time":"6:00 PM – 8:00 PM"}}],"attractions":[{"name":"Creole Nature Trail","description":"Louisiana's Outback: a 180-mile National Scenic Byway through marshes, Gulf beaches, and wildlife refuges. Boardwalks, the Cameron Ferry, and endless alligator sightings make it the state's best free family drive.","officialUrl":"https://www.creolenaturetrail.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Creole%20Nature%20Trail%20Lake%20Charles%20LA","price":"$0 — free (est.)","photos":["assets/gulf-south/images/lake-charles-la-family/attr1-1.jpg","assets/gulf-south/images/lake-charles-la-family/attr1-2.jpg","assets/gulf-south/images/lake-charles-la-family/attr1-3.jpg","assets/gulf-south/images/lake-charles-la-family/attr1-4.jpg"]},{"name":"Sam Houston Jones State Park","description":"A 1,000-acre pine-forest park on the Calcasieu River with hiking trails, canoeing, fishing, and shaded picnic areas. The lazy river and playgrounds make it a local family staple.","officialUrl":"https://www.lastateparks.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Sam%20Houston%20Jones%20State%20Park%20Lake%20Charles%20LA","price":"~$3/person day-use (est.)","photos":["assets/gulf-south/images/lake-charles-la-family/attr2-1.jpg","assets/gulf-south/images/lake-charles-la-family/attr2-2.jpg","assets/gulf-south/images/lake-charles-la-family/attr2-3.jpg","assets/gulf-south/images/lake-charles-la-family/attr2-4.jpg"]},{"name":"Children's Museum of Southwest Louisiana","description":"Lake Charles' hands-on children's museum with water-play tables, climbing structures, a pretend market, and art studios. Bright, modern, and built for ages 2–10.","officialUrl":"https://www.swlakids.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Children%27s%20Museum%20of%20Southwest%20Louisiana%20Lake%20Charles%20LA","price":"$8/person (est.)","photos":["assets/gulf-south/images/lake-charles-la-family/attr3-1.jpg","assets/gulf-south/images/lake-charles-la-family/attr3-2.jpg","assets/gulf-south/images/lake-charles-la-family/attr3-3.jpg","assets/gulf-south/images/lake-charles-la-family/attr3-4.jpg"]},{"name":"Mardi Gras Museum of Imperial Calcasieu","description":"Housed in the 1911 Historic City Hall, this museum holds the world's largest display of Mardi Gras costumes — elaborate king-and-queen gowns, giant headdresses, and parade artifacts, plus costume try-ons for kids.","officialUrl":"https://www.mardigrasmuseum.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mardi%20Gras%20Museum%20of%20Imperial%20Calcasieu%20Lake%20Charles%20LA","price":"$15/adult, $8/child (est.)","photos":["assets/gulf-south/images/lake-charles-la-family/attr4-1.jpg","assets/gulf-south/images/lake-charles-la-family/attr4-2.jpg","assets/gulf-south/images/lake-charles-la-family/attr4-3.jpg","assets/gulf-south/images/lake-charles-la-family/attr4-4.jpg"]}],"restaurants":[{"name":"Steamboat Bill's on the Lake","detail":"Lakefront Cajun seafood landmark — crawfish étouffée and fried alligator with sunset views.","price":"$$"},{"name":"Darrell's","detail":"Lake Charles po'boy institution; the Darrell's Special with jalapeño mayo is the order.","price":"$"},{"name":"Luna Bar & Grill","detail":"Artsy downtown grill with Cajun-Creole plates, live music, and a dog-friendly patio.","price":"$$"}],"rainyDay":["Children's Museum of Southwest Louisiana","Mardi Gras Museum of Imperial Calcasieu","Historic City Hall Arts & Cultural Center"],"driveNotes":"Lake Charles is on I-10, about 2 hours east of Houston and 3 hours west of Baton Rouge — a natural stop on a Gulf Coast road trip. You need a car: the Creole Nature Trail loop takes half a day of driving, and the state park is 20 minutes north of town. Summer is hot and buggy on the trail — bring spray, water, and a full tank of gas.","related":["lafayette-la-cajun","new-orleans-la-city","baton-rouge-la-capital"],"imageAsset":"assets/gulf-south/images/lake-charles-la-family/hero.jpg"},{"id":"oklahoma-city-ok","title":"Oklahoma City, OK: Three-Day Family Adventure","destination":"Oklahoma City, OK","state":"OK","stateName":"Oklahoma","region":"Central Oklahoma","days":3,"tripType":"family adventure","interests":["family","museums","food","outdoors"],"budget":900,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Big-city museums, a wild zoo, and canal rides through Bricktown — OKC is built for families.","overview":"Oklahoma City surprises first-timers: a moving national memorial, one of the country's best zoo expansions, a huge hands-on science museum, and a canal district made for evening strolls. Everything is affordable, parking is easy, and the steakhouse-and-barbecue food scene delivers. Three days fills naturally with the big three attractions plus Bricktown. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["The Oklahoma City National Memorial's Survivor Tree at golden hour","OKC Zoo's elephant habitat and brand-new Expedition Africa","Science Museum Oklahoma's Tinkering Garage and planetarium","A narrated water-taxi ride through Bricktown's canals","Dinner at Cattlemen's — a Stockyards City legend since 1910"],"bestSeason":"March–May; September–November","familyFriendly":"Best for ages 5+. The Memorial's outdoor grounds are stroller-friendly; the museum's upper floors handle the heavier history with care for younger kids.","lat":35.47203,"lng":-97.52107,"itinerary":[{"day":1,"title":"Remembrance & Bricktown","morning":{"stop":"Oklahoma City National Memorial & Museum","description":"Begin at the Memorial's outdoor grounds — the Gates of Time, Reflecting Pool, and Survivor Tree — then tour the museum's chronological exhibits. The children's area honors the 19 young victims with sensitivity; plan 2–3 hours.","cost":"Admission ~$66 for the family (est.)","time":"9:00 AM – 12:00 PM"},"afternoon":{"stop":"Bricktown Water Taxi","description":"Ride the narrated water taxi through the Bricktown canal — a relaxing 40-minute loop past the ballpark, murals, and bridges. Hop off at the Landing for lunch along the canal.","cost":"Taxi ~$46 for the family; lunch ~$55 (est.)","time":"1:30 PM – 4:00 PM"},"evening":{"stop":"Bricktown","description":"Stay in Bricktown for dinner and the evening lights on the canal. The area is flat and walkable, with plenty of kid-friendly patios and an old-timey candy shop for dessert.","cost":"Dinner ~$75 for the family (est.)","time":"6:00 PM – 8:30 PM"}},{"day":2,"title":"Zoo Day","morning":{"stop":"Oklahoma City Zoo","description":"Arrive at opening for the zoo's best hours: Expedition Africa's elephants and rhinos, the sea lion cove, and the children's zoo with lorikeet feeding. The layout is compact enough for a full loop before lunch.","cost":"Admission ~$58 for the family (est.)","time":"9:00 AM – 1:00 PM"},"afternoon":{"stop":"Oklahoma City Zoo","description":"Catch the elephant presentation and the stingray touch tank, then ride the tram or carousel. Cool off at the splash pad in summer months before heading out.","cost":"Snacks and extras ~$30 (est.)","time":"1:00 PM – 4:00 PM"},"evening":{"stop":"Cattlemen's Steakhouse","description":"Drive to Stockyards City for dinner at this 1910 institution — lamb fries for the brave, chicken-fried steak for everyone else. Browse the western shops on Exchange Avenue after.","cost":"Dinner ~$110 for the family (est.)","time":"6:00 PM – 8:00 PM"}},{"day":3,"title":"Science & Sweets","morning":{"stop":"Science Museum Oklahoma","description":"Spend the morning at one of the nation's largest science museums: the Tinkering Garage, CurioCity's kid-sized town, the planetarium, and the towering Science Live shows. Easily a half day for curious kids.","cost":"Admission ~$85 for the family (est.)","time":"10:00 AM – 1:30 PM"},"afternoon":{"stop":"Paseo Arts District","description":"Wander the Spanish Village-style Paseo for galleries, murals, and ice cream. It's a colorful, low-key wind-down after three big days — and the murals make great family photos.","cost":"Treats ~$25 for the family (est.)","time":"2:30 PM – 4:30 PM"},"evening":{"stop":"Kitchen No. 324","description":"Finish downtown at this bright, family-friendly spot in the historic Buick Building — wood-fired pizzas, big salads, and a great patio for the last night.","cost":"Dinner ~$70 for the family (est.)","time":"6:00 PM – 8:00 PM"}}],"attractions":[{"name":"Oklahoma City National Memorial & Museum","description":"The memorial to the 1995 bombing, with the serene outdoor grounds — Gates of Time, Reflecting Pool, Field of Empty Chairs — and a museum tracing the day's events and the community's response. Dignified, moving, and essential.","officialUrl":"https://www.memorialmuseum.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Oklahoma%20City%20National%20Memorial%20Oklahoma%20City%20OK","price":"$18/adult, $16/senior & military, $15/student (est.)","photos":["assets/gulf-south/images/oklahoma-city-ok/attr1-1.jpg","assets/gulf-south/images/oklahoma-city-ok/attr1-2.jpg","assets/gulf-south/images/oklahoma-city-ok/attr1-3.jpg","assets/gulf-south/images/oklahoma-city-ok/attr1-4.jpg"]},{"name":"Oklahoma City Zoo","description":"A 130-acre zoo famous for its elephant program and the new Expedition Africa habitat, plus sea lions, a children's zoo, and seasonal rides. One of the best mid-size zoos in the country.","officialUrl":"https://www.okczoo.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Oklahoma%20City%20Zoo%20Oklahoma%20City%20OK","price":"$16/adult, $13/child & senior (est.)","photos":["assets/gulf-south/images/oklahoma-city-ok/attr2-1.jpg","assets/gulf-south/images/oklahoma-city-ok/attr2-2.jpg","assets/gulf-south/images/oklahoma-city-ok/attr2-3.jpg","assets/gulf-south/images/oklahoma-city-ok/attr2-4.jpg"]},{"name":"Science Museum Oklahoma","description":"One of America's largest hands-on science museums, with CurioCity's eight kid-powered neighborhoods, the Tinkering Garage maker space, a planetarium, and daily Science Live demonstrations.","officialUrl":"https://www.sciencemuseumok.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Science%20Museum%20Oklahoma%20Oklahoma%20City%20OK","price":"~$23/person (est.)","photos":["assets/gulf-south/images/oklahoma-city-ok/attr3-1.jpg","assets/gulf-south/images/oklahoma-city-ok/attr3-2.jpg","assets/gulf-south/images/oklahoma-city-ok/attr3-3.jpg","assets/gulf-south/images/oklahoma-city-ok/attr3-4.jpg"]},{"name":"Bricktown Water Taxi","description":"Narrated open-air boat rides along the Bricktown Canal, looping past the ballpark, public art, and bridges with hop-on-hop-off stops. The most relaxing way to see downtown's entertainment district.","officialUrl":"https://www.bricktownwatertaxi.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Bricktown%20Water%20Taxi%20Oklahoma%20City%20OK","price":"$13/adult, $10/youth (est.)","photos":["assets/gulf-south/images/oklahoma-city-ok/attr4-1.jpg","assets/gulf-south/images/oklahoma-city-ok/attr4-2.jpg","assets/gulf-south/images/oklahoma-city-ok/attr4-3.jpg","assets/gulf-south/images/oklahoma-city-ok/attr4-4.jpg"]}],"restaurants":[{"name":"Cattlemen's Steakhouse","detail":"Stockyards City legend since 1910 — mesquite-grilled steaks in a room full of western history.","price":"$$"},{"name":"Cheever's Cafe","detail":"Uptown flower-shop-turned-café famous for chicken-fried steak and pecan pie.","price":"$$"},{"name":"Kitchen No. 324","detail":"Bright downtown spot in a historic auto building — wood-fired pizza and a great patio.","price":"$"}],"rainyDay":["Science Museum Oklahoma — a full rainy day easily","Oklahoma City National Memorial & Museum","Oklahoma City Museum of Art downtown"],"driveNotes":"OKC is a driving city — you'll want a car, and parking is cheap and plentiful everywhere except peak Bricktown nights. It's 3 hours north of Dallas and 2 hours south of Wichita on I-35, making it a natural road-trip hub. Summer heat is real; plan zoos and memorial grounds for mornings.","related":["tulsa-ok","norman-ok","wichita-mountains-ok"],"imageAsset":"assets/gulf-south/images/oklahoma-city-ok/hero.jpg"},{"id":"tulsa-ok","title":"Tulsa, OK: Three-Day Family Getaway","destination":"Tulsa, OK","state":"OK","stateName":"Oklahoma","region":"Green Country","days":3,"tripType":"family adventure","interests":["family","museums","food","outdoors"],"budget":850,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"A world-class riverfront park, art-deco streets, and sharks in the suburbs — Tulsa delights.","overview":"Tulsa's Gathering Place is arguably the best urban park in America — free, enormous, and built for kids — and it's surrounded by a walkable art-deco downtown, a top-tier art museum with glorious gardens, and one of the country's best inland aquariums. Add legendary barbecue and you have a long weekend that rivals any big-city trip. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Gathering Place — 100 free acres of playgrounds, gardens, and riverfront","Philbrook's villa, gardens, and kid-friendly art hunts","The Oklahoma Aquarium's shark tunnel and touch tanks","Tulsa Zoo's Lost Kingdom elephant and tiger exhibits","Burn Co BBQ's burnt ends — worth planning lunch around"],"bestSeason":"April–June; September–October","familyFriendly":"Best for ages 4+. Gathering Place is stroller paradise with shaded play areas; the aquarium and zoo are fully accessible.","lat":36.15011,"lng":-95.99352,"itinerary":[{"day":1,"title":"Gathering Place Day","morning":{"stop":"Gathering Place","description":"Give the whole morning to Tulsa's 100-acre riverfront park: the five-acre Chapman Adventure Playground, the Sky Garden, and the mist mountain. It's all free, and the lodge has clean restrooms and a café.","cost":"Free (est.)","time":"9:30 AM – 1:00 PM"},"afternoon":{"stop":"Gathering Place","description":"After a picnic lunch on the lawns, hit the boathouse for paddle boats, the sports courts, and the wetland gardens. Kids won't want to leave — plan accordingly.","cost":"Boat rental ~$20; snacks ~$25 (est.)","time":"1:30 PM – 5:00 PM"},"evening":{"stop":"Burn Co BBQ","description":"Drive to Jenks or the original for burnt ends, ribs, and jalapeño-cheese sausage. Counter service, picnic tables, and zero pretense — the family favorite of the trip.","cost":"Dinner ~$65 for the family (est.)","time":"6:00 PM – 7:30 PM"}},{"day":2,"title":"Art & Animals","morning":{"stop":"Philbrook Museum of Art","description":"Tour the Italianate villa and its 25 acres of formal gardens — kids get art-hunt activity sheets, and the gardens alone are worth the trip. The rotating exhibitions skew family-friendly.","cost":"Admission ~$64 for the family (est.)","time":"10:00 AM – 1:00 PM"},"afternoon":{"stop":"Tulsa Zoo","description":"Afternoon at the zoo's Lost Kingdom complex — tigers, snow leopards, and elephants — plus the rainforest building and sea lions. The train and carousel are kid catnip.","cost":"Admission ~$70 for the family (est.)","time":"2:00 PM – 5:00 PM"},"evening":{"stop":"El Guapo's Cantina","description":"Casual Mexican in the Blue Dome District — big margaritas for grownups, quesadillas and street tacos for kids, and a patio made for warm evenings.","cost":"Dinner ~$60 for the family (est.)","time":"6:30 PM – 8:00 PM"}},{"day":3,"title":"Sharks & Downtown","morning":{"stop":"Oklahoma Aquarium","description":"Drive 15 minutes to Jenks for the aquarium: walk the shark tunnel, touch stingrays and starfish, and watch the sea turtles. The Aquatic Oklahoma gallery is a love letter to local rivers.","cost":"Admission ~$80 for the family (est.)","time":"10:00 AM – 1:00 PM"},"afternoon":{"stop":"Downtown Tulsa","description":"Back downtown for the art-deco architecture walk — the Boston Avenue church and Philcade building wow kids who like big buildings. Grab coffee and browse the Woody Guthrie Center's exhibits.","cost":"Woody Guthrie Center ~$30 for the family (est.)","time":"2:00 PM – 4:30 PM"},"evening":{"stop":"Andolini's Pizzeria","description":"Finish at this Tulsa-born pizzeria — creative pies, a gelato counter, and a fun, loud room that's made for families. The Nutella pizza is the kids' dessert order.","cost":"Dinner ~$65 for the family (est.)","time":"6:00 PM – 7:30 PM"}}],"attractions":[{"name":"Gathering Place","description":"Tulsa's 100-acre riverfront park — free and consistently ranked among the world's best new parks. Adventure playgrounds, paddle boats, gardens, sports courts, and the lodge café line the Arkansas River.","officialUrl":"https://www.gatheringplace.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Gathering%20Place%20Tulsa%20OK","price":"$0 — free admission (est.)","photos":["assets/gulf-south/images/tulsa-ok/attr1-1.jpg","assets/gulf-south/images/tulsa-ok/attr1-2.jpg","assets/gulf-south/images/tulsa-ok/attr1-3.jpg","assets/gulf-south/images/tulsa-ok/attr1-4.jpg"]},{"name":"Philbrook Museum of Art","description":"A 1920s Italianate villa turned art museum, set in 25 acres of formal gardens with sculptures, a tempietto, and wandering paths. The collection spans Native American to contemporary, with strong family programming.","officialUrl":"https://www.philbrook.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Philbrook%20Museum%20of%20Art%20Tulsa%20OK","price":"$22/adult, $10/youth (est.)","photos":["assets/gulf-south/images/tulsa-ok/attr2-1.jpg","assets/gulf-south/images/tulsa-ok/attr2-2.jpg","assets/gulf-south/images/tulsa-ok/attr2-3.jpg","assets/gulf-south/images/tulsa-ok/attr2-4.jpg"]},{"name":"Tulsa Zoo","description":"A 84-acre zoo known for its Lost Kingdom exhibit complex — tigers, snow leopards, red pandas, and elephants — plus a rainforest building, sea lions, and a children's petting area.","officialUrl":"https://www.tulsazoo.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Tulsa%20Zoo%20Tulsa%20OK","price":"$20/adult, $14/child (est.)","photos":["assets/gulf-south/images/tulsa-ok/attr3-1.jpg","assets/gulf-south/images/tulsa-ok/attr3-2.jpg","assets/gulf-south/images/tulsa-ok/attr3-3.jpg","assets/gulf-south/images/tulsa-ok/attr3-4.jpg"]},{"name":"Oklahoma Aquarium","description":"In nearby Jenks, the state's largest aquarium with a walk-through shark tunnel, touch tanks, sea turtles, and the Aquatic Oklahoma gallery of native fish. The bull sharks are the stars.","officialUrl":"https://www.okaquarium.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Oklahoma%20Aquarium%20Jenks%20OK","price":"$25/adult, $19/child (est.)","photos":["assets/gulf-south/images/tulsa-ok/attr4-1.jpg","assets/gulf-south/images/tulsa-ok/attr4-2.jpg","assets/gulf-south/images/tulsa-ok/attr4-3.jpg","assets/gulf-south/images/tulsa-ok/attr4-4.jpg"]}],"restaurants":[{"name":"Burn Co BBQ","detail":"Tulsa barbecue institution — burnt ends, ribs, and jalapeño-cheese sausage, counter-service casual.","price":"$$"},{"name":"El Guapo's Cantina","detail":"Blue Dome District Mexican with street tacos, big margaritas, and a buzzing patio.","price":"$$"},{"name":"Andolini's Pizzeria","detail":"Tulsa-born pizzeria with creative pies and a gelato counter — loud, fun, family-perfect.","price":"$$"}],"rainyDay":["Oklahoma Aquarium in Jenks","Philbrook Museum of Art","Tulsa Children's Museum Discovery Lab"],"driveNotes":"Tulsa is 90 minutes northeast of Oklahoma City on I-44 — an easy two-city combo. You'll want a car: Gathering Place, Philbrook, the zoo, and the aquarium are spread across town. Downtown parking is cheap; the aquarium is a straight 15-minute shot down Riverside Drive to Jenks.","related":["oklahoma-city-ok","norman-ok","broken-bow-ok"],"imageAsset":"assets/gulf-south/images/tulsa-ok/hero.jpg"},{"id":"wichita-mountains-ok","title":"Wichita Mountains, OK: Two-Day Wildlife Escape","destination":"Wichita Mountains, OK","state":"OK","stateName":"Oklahoma","region":"Southwest Oklahoma","days":2,"tripType":"nature getaway","interests":["family","outdoors","nature","scenic"],"budget":400,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Free-roaming bison, granite peaks, and a cobblestone resort town — the West begins here.","overview":"The Wichita Mountains Wildlife Refuge is one of America's oldest wildlife refuges — 59,000 acres where bison, elk, and longhorn cattle roam free beneath ancient granite domes. Pair it with the quirky cobblestone town of Medicine Park and a drive up Mount Scott, and you have a two-day nature escape that feels like the frontier. Almost everything is free. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Bison and longhorn herds grazing right by the road","The Mount Scott summit drive — 360-degree prairie views","Swimming and wading in Medicine Park's Bath Lake","Elk bugling in the fall (and prairie dogs year-round)","A Meersburger the size of your head at the Meers Store"],"bestSeason":"March–May; September–November","familyFriendly":"Best for ages 5+. Trails are short and kid-doable; keep distance from bison and longhorns — they're wild animals, not photo props.","lat":34.72758,"lng":-98.5026,"itinerary":[{"day":1,"title":"Refuge & Mount Scott","morning":{"stop":"Wichita Mountains Wildlife Refuge","description":"Enter the refuge and drive the wildlife loop slowly — bison herds, Texas longhorns, and prairie dog towns are visible from the car. Stop at the visitor center for the exhibits and junior ranger packets.","cost":"Free (est.)","time":"9:00 AM – 12:00 PM"},"afternoon":{"stop":"Mount Scott","description":"Drive the winding road to the 2,464-foot summit for panoramic views of the whole refuge. Hike the short summit trail, then descend for a picnic at one of the lakeside areas.","cost":"Free; picnic ~$30 (est.)","time":"1:00 PM – 4:30 PM"},"evening":{"stop":"Meers Store & Restaurant","description":"Dinner at the legendary Meers Store — famous for its giant Meersburgers (Texas longhorn beef) served in a tin-sided 1901 building. Cash and cards; expect a wait on weekends.","cost":"Dinner ~$60 for the family (est.)","time":"5:30 PM – 7:30 PM"}},{"day":2,"title":"Medicine Park Day","morning":{"stop":"Medicine Park","description":"Explore Oklahoma's first resort town — cobblestone streets, red-rock buildings, and quirky shops along Medicine Creek. In summer, swim and wade at Bath Lake; year-round, browse the galleries and candy shops.","cost":"Free to explore (est.)","time":"10:00 AM – 1:00 PM"},"afternoon":{"stop":"Medicine Park Aquarium & Natural Sciences Center","description":"Visit the small aquarium and natural sciences center on the creek — native fish, reptiles, and hands-on exhibits about the refuge ecosystem. Compact and perfect for younger kids.","cost":"Admission ~$50 for the family (est.)","time":"2:00 PM – 4:00 PM"},"evening":{"stop":"The Plantation","description":"Dinner back in Medicine Park at this creekside restaurant — steaks, catfish, and a patio over the water. End the evening with ice cream on the cobblestone main street.","cost":"Dinner ~$75 for the family (est.)","time":"5:30 PM – 7:30 PM"}}],"attractions":[{"name":"Wichita Mountains Wildlife Refuge","description":"A 59,000-acre national wildlife refuge established in 1901, home to free-roaming bison, elk, and Texas longhorn herds. Scenic drives, short trails, and lakes dot the ancient granite landscape.","officialUrl":"https://www.fws.gov/refuge/wichita-mountains","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Wichita%20Mountains%20Wildlife%20Refuge%20Oklahoma","price":"$0 — free admission (est.)","photos":["assets/gulf-south/images/wichita-mountains-ok/attr1-1.jpg","assets/gulf-south/images/wichita-mountains-ok/attr1-2.jpg","assets/gulf-south/images/wichita-mountains-ok/attr1-3.jpg","assets/gulf-south/images/wichita-mountains-ok/attr1-4.jpg"]},{"name":"Mount Scott","description":"The refuge's signature 2,464-foot granite peak, reached by a scenic 3-mile drive with pullouts and a summit trail. The 360-degree view stretches across the whole Wichita range and prairie.","officialUrl":"https://www.fws.gov/refuge/wichita-mountains","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mount%20Scott%20Oklahoma","price":"$0 — free (est.)","photos":["assets/gulf-south/images/wichita-mountains-ok/attr2-1.jpg","assets/gulf-south/images/wichita-mountains-ok/attr2-2.jpg","assets/gulf-south/images/wichita-mountains-ok/attr2-3.jpg","assets/gulf-south/images/wichita-mountains-ok/attr2-4.jpg"]},{"name":"Medicine Park","description":"Oklahoma's first resort town (1908), a cobblestone village of red native-stone buildings on Medicine Creek. Swim at Bath Lake, browse art galleries and taffy shops, and catch live music on summer weekends.","officialUrl":"https://www.medicinepark.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Medicine%20Park%20Oklahoma","price":"$0 — free to explore (est.)","photos":["assets/gulf-south/images/wichita-mountains-ok/attr3-1.jpg","assets/gulf-south/images/wichita-mountains-ok/attr3-2.jpg","assets/gulf-south/images/wichita-mountains-ok/attr3-3.jpg","assets/gulf-south/images/wichita-mountains-ok/attr3-4.jpg"]},{"name":"Medicine Park Aquarium & Natural Sciences Center","description":"A small creekside aquarium and science center with native Oklahoma fish, reptiles, and interactive exhibits on the Wichita Mountains ecosystem. A great 1–2 hour stop for younger naturalists.","officialUrl":"https://www.mpmns.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Medicine%20Park%20Aquarium%20Medicine%20Park%20OK","price":"$15/adult, $10/child (est.)","photos":["assets/gulf-south/images/wichita-mountains-ok/attr4-1.jpg","assets/gulf-south/images/wichita-mountains-ok/attr4-2.jpg","assets/gulf-south/images/wichita-mountains-ok/attr4-3.jpg","assets/gulf-south/images/wichita-mountains-ok/attr4-4.jpg"]}],"restaurants":[{"name":"Meers Store & Restaurant","detail":"Legendary 1901 burger joint famous for the giant longhorn-beef Meersburger — worth the wait.","price":"$"},{"name":"The Plantation","detail":"Creekside Medicine Park restaurant with steaks, catfish, and a patio over the water.","price":"$$"},{"name":"Ann's Country Kitchen","detail":"Homestyle breakfast and lunch spot in the refuge gateway — chicken-fried everything.","price":"$"}],"rainyDay":["Medicine Park Aquarium & Natural Sciences Center","Museum of the Great Plains in Lawton (check reopening status)","Comanche National Museum in Lawton"],"driveNotes":"The refuge is 90 minutes southwest of Oklahoma City via I-44 and OK-49 — an easy day trip or overnight. The refuge gates open at dawn; arrive early for the most wildlife activity. Cell service is spotty in the mountains, so download maps ahead. Fill up in Lawton or Medicine Park — no gas inside the refuge.","related":["oklahoma-city-ok","broken-bow-ok","norman-ok"],"imageAsset":"assets/gulf-south/images/wichita-mountains-ok/hero.jpg"},{"id":"broken-bow-ok","title":"Broken Bow, OK: Three-Day Cabin Adventure","destination":"Broken Bow, OK","state":"OK","stateName":"Oklahoma","region":"Choctaw Country","days":3,"tripType":"cabin getaway","interests":["family","outdoors","nature","scenic"],"budget":850,"budgetNote":"For 2 adults + 2 kids: activities, meals, and park fees; cabin rental not included.","tagline":"Pine forests, a glass-clear lake, and ziplines through the canopy — Oklahoma's mountain escape.","overview":"Broken Bow and Beavers Bend are Oklahoma's answer to the Smokies: towering pines, the clear waters of Broken Bow Lake, and a whole industry of cabins, outfitters, and family adventures. Hike old-growth forest in the morning, swim the lake in the afternoon, and end the day on a cabin porch. It's the state's most popular family getaway for a reason. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Kayak or swim the gin-clear waters of Broken Bow Lake","Hike among 100-foot pines in Beavers Bend State Park","Zipline through the forest canopy with Rugaru Adventures","Hand-feed camels and lemurs at the safari park","Stargazing from a cabin hot tub — some of Oklahoma's darkest skies"],"bestSeason":"April–June; September–November","familyFriendly":"Best for ages 5+. Trails range from easy loops to rugged; ziplines have weight minimums (usually 70+ lbs) — check before booking.","lat":34.02789,"lng":-94.73956,"itinerary":[{"day":1,"title":"Forest & Falls","morning":{"stop":"Beavers Bend State Park","description":"Hike the Friends Trail loop and the David L. Boren Trail through towering pines and along Mountain Fork River. Stop at the Forest Heritage Center area for the lake overlook.","cost":"Free (est.)","time":"9:00 AM – 12:30 PM"},"afternoon":{"stop":"Beavers Bend Safari Park","description":"Drive-through and walk-through safari with camels, zebras, lemurs, and kangaroos — kids hand-feed many of the animals from the car. The walk-through section has the petting zoo.","cost":"Admission ~$90 for the family (est.)","time":"1:30 PM – 4:30 PM"},"evening":{"stop":"Grateful Head Pizza Oven & Tap Room","description":"Wood-fired pizza and local brews (root beer for the kids) in a funky, music-filled room. The patio is made for post-safari unwinding.","cost":"Dinner ~$65 for the family (est.)","time":"6:00 PM – 7:30 PM"}},{"day":2,"title":"Lake Day","morning":{"stop":"Broken Bow Lake","description":"Rent a pontoon or kayaks and spend the morning on one of the clearest lakes in the South. Swim coves, cliff views, and quiet inlets — bring a cooler and make a day of it.","cost":"Kayak rental ~$80 for the family (est.)","time":"9:30 AM – 1:00 PM"},"afternoon":{"stop":"Broken Bow Lake","description":"More lake time: swim at the Stevens Gap area or try the jet-ski rentals. Shaded picnic areas at the state park make an easy lunch base.","cost":"Picnic ~$30 (est.)","time":"1:30 PM – 4:30 PM"},"evening":{"stop":"The Lookout Kitchen","description":"Dinner inside Beavers Bend State Park at this lodge restaurant — burgers, catfish, and fried pickles with big windows on the pines.","cost":"Dinner ~$60 for the family (est.)","time":"6:00 PM – 7:30 PM"}},{"day":3,"title":"Zipline Morning","morning":{"stop":"Rugaru Adventures","description":"Fly the treetops on Oklahoma's longest zipline course — six lines through the pine canopy, plus the giant swing for the brave. Book the first slot of the day for cooler air and smaller groups.","cost":"Zipline ~$356 for the family (est.)","time":"9:00 AM – 12:00 PM"},"afternoon":{"stop":"Hochatown","description":"Browse the Hochatown shops — fudge, souvenirs, and the famous Pete's Place-adjacent wineries for grownups. Grab a late lunch before the drive home.","cost":"Lunch and treats ~$55 (est.)","time":"12:30 PM – 3:00 PM"},"evening":{"stop":"Abendigo's Grill & Patio","description":"One last patio dinner in Hochatown — steaks, seafood, and live music on summer weekends. The fire pits are perfect for a cool fall evening.","cost":"Dinner ~$85 for the family (est.)","time":"5:30 PM – 7:30 PM"}}],"attractions":[{"name":"Beavers Bend State Park","description":"Oklahoma's most beloved state park: 3,000+ acres of pine forest on Mountain Fork River with hiking trails, trout fishing, canoeing, and the Forest Heritage Center. The David L. Boren Trail is a hiker favorite.","officialUrl":"https://www.travelok.com/beaversbend","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Beavers%20Bend%20State%20Park%20Broken%20Bow%20OK","price":"$0 — free entry (est.)","photos":["assets/gulf-south/images/broken-bow-ok/attr1-1.jpg","assets/gulf-south/images/broken-bow-ok/attr1-2.jpg","assets/gulf-south/images/broken-bow-ok/attr1-3.jpg","assets/gulf-south/images/broken-bow-ok/attr1-4.jpg"]},{"name":"Broken Bow Lake","description":"A 14,000-acre Army Corps of Engineers lake famous for its clear water, pine-lined shores, and excellent bass fishing. Marinas rent pontoons, kayaks, and jet skis; swim coves dot the shoreline.","officialUrl":"https://www.swt.usace.army.mil/Missions/Recreation/Lakes/Broken-Bow-Lake/","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Broken%20Bow%20Lake%20Broken%20Bow%20OK","price":"$0 — free access (est.)","photos":["assets/gulf-south/images/broken-bow-ok/attr2-1.jpg","assets/gulf-south/images/broken-bow-ok/attr2-2.jpg","assets/gulf-south/images/broken-bow-ok/attr2-3.jpg","assets/gulf-south/images/broken-bow-ok/attr2-4.jpg"]},{"name":"Rugaru Adventures","description":"Oklahoma's premier zipline canopy tour — six ziplines soaring through the Ouachita forest canopy, plus a giant swing and free-fall experiences. Guides are top-notch and safety-obsessed.","officialUrl":"https://www.rugaruadventures.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Rugaru%20Adventures%20Broken%20Bow%20OK","price":"$89/person (est.)","photos":["assets/gulf-south/images/broken-bow-ok/attr3-1.jpg","assets/gulf-south/images/broken-bow-ok/attr3-2.jpg","assets/gulf-south/images/broken-bow-ok/attr3-3.jpg","assets/gulf-south/images/broken-bow-ok/attr3-4.jpg"]},{"name":"Beavers Bend Safari Park","description":"A drive-through safari with 30+ species — camels, zebras, bison, and lemurs — that you feed from your car, plus a walk-through petting zoo. Kids talk about the camel kisses for weeks.","officialUrl":"https://www.beaversbendsafaripark.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Beavers%20Bend%20Safari%20Park%20Broken%20Bow%20OK","price":"~$25/person (est.)","photos":["assets/gulf-south/images/broken-bow-ok/attr4-1.jpg","assets/gulf-south/images/broken-bow-ok/attr4-2.jpg","assets/gulf-south/images/broken-bow-ok/attr4-3.jpg","assets/gulf-south/images/broken-bow-ok/attr4-4.jpg"]}],"restaurants":[{"name":"Grateful Head Pizza Oven & Tap Room","detail":"Wood-fired pizza and local brews in a funky, music-filled Hochatown room.","price":"$$"},{"name":"Abendigo's Grill & Patio","detail":"Steaks, seafood, and live music on a big Hochatown patio with fire pits.","price":"$$"},{"name":"The Lookout Kitchen","detail":"Casual lodge restaurant inside Beavers Bend State Park — burgers and catfish with pine views.","price":"$"}],"rainyDay":["Beavers Bend Safari Park (much is drive-through)","Girls Gone Wine tasting room in Hochatown (adults)","Hochatown's escape rooms and indoor mini-golf"],"driveNotes":"Broken Bow is 3.5 hours southeast of Oklahoma City and 3 hours north of Dallas — solidly a weekend destination, so book cabins early for fall and holidays. Hochatown (the cabin district) is 10 minutes north of the town of Broken Bow; most attractions cluster around it. Gas up before the lake — stations are sparse on the park roads.","related":["tulsa-ok","wichita-mountains-ok","oklahoma-city-ok"],"imageAsset":"assets/gulf-south/images/broken-bow-ok/hero.jpg"},{"id":"norman-ok","title":"Norman, OK: Two-Day College Town Getaway","destination":"Norman, OK","state":"OK","stateName":"Oklahoma","region":"Central Oklahoma","days":2,"tripType":"weekend getaway","interests":["family","museums","amusement-parks","food"],"budget":500,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Dinosaurs, free art, and Sooner spirit — the friendliest college town in the plains.","overview":"Norman is the classic college-town weekend: a world-class natural history museum with towering dinosaurs, a free art museum on a gorgeous campus, a water park for hot afternoons, and Campus Corner's student-priced eats. It's 20 minutes from Oklahoma City, so it pairs perfectly — or stands alone as an easy, affordable two days. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["The Sam Noble Museum's towering Apatosaurus and mammoth","Free admission to the Fred Jones Jr. Museum of Art","Andy Alligator's water slides and go-karts","A stroll through OU's Cherokee Gothic campus","Campus Corner's cheap eats and Sooner shopping"],"bestSeason":"March–May; September–November","familyFriendly":"Best for ages 4+. Both museums are stroller-friendly; the water park has height minimums on big slides.","lat":35.22097,"lng":-97.4461,"itinerary":[{"day":1,"title":"Dinosaurs & Campus","morning":{"stop":"Sam Noble Oklahoma Museum of Natural History","description":"Spend the morning among the giants: a 75-foot Apatosaurus, a mammoth, and Oklahoma's Ice Age fossils, plus the Hall of Natural Wonders' dioramas. The discovery room lets kids dig for fossils.","cost":"Admission ~$40 for the family (est.)","time":"10:00 AM – 1:00 PM"},"afternoon":{"stop":"Fred Jones Jr. Museum of Art","description":"Walk across campus to this free art museum — the Weitzenhoffer Collection of French Impressionism, Native American art, and the striking Lester Wing. Quiet, beautiful, and a great contrast to the morning's dinosaurs.","cost":"Free (est.)","time":"2:00 PM – 4:00 PM"},"evening":{"stop":"The Mont","description":"Dinner on Campus Corner at this Norman institution — famous for giant calzones and cheap pitchers. The patio people-watching is half the fun.","cost":"Dinner ~$55 for the family (est.)","time":"5:30 PM – 7:30 PM"}},{"day":2,"title":"Water Park Day","morning":{"stop":"Andy Alligator's Fun Park & Water Park","description":"Go-karts, mini golf, and batting cages in the morning before the heat builds. The park opens early in summer; arrive at opening for the shortest lines.","cost":"Wristbands ~$100 for the family (est.)","time":"10:30 AM – 1:00 PM"},"afternoon":{"stop":"Andy Alligator's Fun Park & Water Park","description":"Switch to the water park: slides, the lazy river, and the wave pool. Rent a locker, reapply sunscreen, and let the kids run the afternoon.","cost":"Included with wristbands (est.)","time":"1:00 PM – 5:00 PM"},"evening":{"stop":"Benvenuti's Ristorante","description":"One nice dinner to close the trip — Norman's beloved Italian spot for wood-fired pizzas, handmade pasta, and a romantic-but-family-welcoming dining room.","cost":"Dinner ~$90 for the family (est.)","time":"6:30 PM – 8:30 PM"}}],"attractions":[{"name":"Sam Noble Oklahoma Museum of Natural History","description":"OU's natural history museum — one of the finest university museums in the country — with a 75-foot Apatosaurus, Ice Age megafauna, and deep dives into Oklahoma's 300-million-year natural past.","officialUrl":"https://www.samnoblemuseum.ou.edu","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Sam%20Noble%20Museum%20Norman%20OK","price":"$12/adult, $8/child (est.)","photos":["assets/gulf-south/images/norman-ok/attr1-1.jpg","assets/gulf-south/images/norman-ok/attr1-2.jpg","assets/gulf-south/images/norman-ok/attr1-3.jpg","assets/gulf-south/images/norman-ok/attr1-4.jpg"]},{"name":"Fred Jones Jr. Museum of Art","description":"OU's free art museum housing the Weitzenhoffer Collection (Monet, Renoir, Van Gogh), one of the great university collections of French Impressionism, plus strong Native American and contemporary holdings.","officialUrl":"https://www.ou.edu/fjjma","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Fred%20Jones%20Jr%20Museum%20of%20Art%20Norman%20OK","price":"$0 — free admission (est.)","photos":["assets/gulf-south/images/norman-ok/attr2-1.jpg","assets/gulf-south/images/norman-ok/attr2-2.jpg","assets/gulf-south/images/norman-ok/attr2-3.jpg","assets/gulf-south/images/norman-ok/attr2-4.jpg"]},{"name":"Andy Alligator's Fun Park & Water Park","description":"Norman's family amusement complex: go-karts, mini golf, batting cages, and laser tag plus a full water park with slides, wave pool, and lazy river. The summer headquarters for local families.","officialUrl":"https://www.andyalligators.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Andy%20Alligator%27s%20Fun%20Park%20Norman%20OK","price":"~$25/person wristband (est.)","photos":["assets/gulf-south/images/norman-ok/attr3-1.jpg","assets/gulf-south/images/norman-ok/attr3-2.jpg","assets/gulf-south/images/norman-ok/attr3-3.jpg","assets/gulf-south/images/norman-ok/attr3-4.jpg"]},{"name":"University of Oklahoma","description":"One of America's most beautiful campuses — Cherokee Gothic limestone buildings, the Bizzell Library's Great Reading Room, and the South Oval's elm-lined walks. Self-guided strolls are free and lovely.","officialUrl":"https://www.ou.edu","mapsUrl":"https://www.google.com/maps/search/?api=1&query=University%20of%20Oklahoma%20Norman%20OK","price":"$0 — free to explore (est.)","photos":["assets/gulf-south/images/norman-ok/attr4-1.jpg","assets/gulf-south/images/norman-ok/attr4-2.jpg","assets/gulf-south/images/norman-ok/attr4-3.jpg","assets/gulf-south/images/norman-ok/attr4-4.jpg"]}],"restaurants":[{"name":"The Mont","detail":"Campus Corner institution famous for giant calzones, cheap pitchers, and people-watching.","price":"$"},{"name":"Tarahumara's","detail":"Beloved local Mexican spot — generous portions, strong margaritas, family-friendly.","price":"$$"},{"name":"Benvenuti's Ristorante","detail":"Norman's special-occasion Italian — wood-fired pizza, handmade pasta, warm dining room.","price":"$$$"}],"rainyDay":["Sam Noble Museum — a full rainy morning easily","Fred Jones Jr. Museum of Art (free)","Norman's Sooner Theatre for a family matinee"],"driveNotes":"Norman is 20 minutes south of Oklahoma City on I-35 — combine it with OKC or visit solo. Campus parking is free on weekends; use the lots near the museums. Avoid home football Saturdays in the fall, when the whole town (and every restaurant) is packed by noon.","related":["oklahoma-city-ok","tulsa-ok","wichita-mountains-ok"],"imageAsset":"assets/gulf-south/images/norman-ok/hero.jpg"},{"id":"san-antonio-tx","title":"San Antonio, TX: Three-Day Family Adventure","destination":"San Antonio, TX","state":"TX","stateName":"Texas","region":"South Central Texas","days":3,"tripType":"family adventure","interests":["family","historical-sites","food","outdoors"],"budget":800,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Remember the Alamo, then ride the river — San Antonio is Texas history at its most walkable.","overview":"San Antonio is Texas's most family-friendly big city: the Alamo and four UNESCO missions are free, the River Walk is a 15-mile shaded playground, and the zoo rivals any in the state. Three days gives you history, river time, and wildlife without rushing — and the tacos are non-negotiable. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["The Alamo — free, moving, and right downtown","A narrated river barge cruise through the River Walk","Four UNESCO World Heritage missions along the Mission Trail","San Antonio Zoo's Africa Live! and the new Naylor Rhinos","Puffy tacos and margaritas on the river at sunset"],"bestSeason":"February–May; October–November","familyFriendly":"Best for ages 5+. The Alamo and missions are stroller-friendly; the River Walk has stairs — use the elevator-equipped access points with strollers.","lat":29.42458,"lng":-98.49461,"itinerary":[{"day":1,"title":"The Alamo & the River Walk","morning":{"stop":"The Alamo","description":"Start at the Shrine of Texas Liberty — arrive at opening for the free timed entry, then tour the church, the Long Barrack museum, and the gardens. The living-history demos (muzzle-loading, blacksmithing) run most days.","cost":"Free (reserve timed entry ahead) (est.)","time":"9:00 AM – 12:00 PM"},"afternoon":{"stop":"San Antonio River Walk","description":"Board a Go Rio narrated barge cruise for the 35-minute loop through the downtown bend — the easiest way to orient. Then walk the shaded river paths, stopping at the shops and the Selena bridge.","cost":"Barge cruise ~$52 for the family (est.)","time":"1:30 PM – 4:30 PM"},"evening":{"stop":"Boudro's Texas Bistro","description":"Dinner on the river at this Texas bistro institution — tableside guacamole, prickly pear margaritas for grownups, and a kids' menu that goes beyond nuggets. Book ahead for riverfront tables.","cost":"Dinner ~$110 for the family (est.)","time":"6:00 PM – 8:00 PM"}},{"day":2,"title":"Missions Trail","morning":{"stop":"San Antonio Missions National Historical Park","description":"Drive or bike the Mission Trail to Concepción, San José, San Juan, and Espada — four active 1700s missions, all free. Mission San José's Rose Window and Sunday mariachi mass are the highlights.","cost":"Free (est.)","time":"9:00 AM – 1:00 PM"},"afternoon":{"stop":"San Antonio Missions National Historical Park","description":"Finish the last missions, then picnic on the grounds. The park's hike-and-bike trail connects all four — rent bikes at the San José trailhead for the full experience.","cost":"Bike rental ~$40 for the family (est.)","time":"1:30 PM – 4:00 PM"},"evening":{"stop":"Rosario's","description":"Casual Southtown Mexican — the puffy tacos and fish tacos are local legends, and the patio is made for warm evenings. Walkable from the Blue Star arts complex.","cost":"Dinner ~$65 for the family (est.)","time":"6:00 PM – 7:30 PM"}},{"day":3,"title":"Zoo Day","morning":{"stop":"San Antonio Zoo","description":"Spend the morning at the 50-acre zoo in Brackenridge Park: Africa Live! hippos and crocs, the new rhino habitat, the train ride, and the butterfly house. Arrive at opening for the most active animals.","cost":"Admission ~$120 for the family (est.)","time":"9:30 AM – 1:30 PM"},"afternoon":{"stop":"Brackenridge Park","description":"Picnic and paddle boats in Brackenridge Park, or add the nearby Witte Museum's dinosaur and Texas history exhibits. The Japanese Tea Garden's waterfalls are a peaceful wind-down.","cost":"Witte Museum ~$56 for the family (est.)","time":"2:00 PM – 5:00 PM"},"evening":{"stop":"The Guenther House","description":"Farewell breakfast-for-dinner at the historic Pioneer Flour Mills mansion — chicken and waffles on the river terrace. A San Antonio tradition since forever.","cost":"Dinner ~$70 for the family (est.)","time":"6:00 PM – 8:00 PM"}}],"attractions":[{"name":"The Alamo","description":"The 1718 mission and 1836 battle site at the heart of Texas identity, now with an expanded museum and free timed-entry tours. The church, the Long Barrack, and the living-history demos anchor any San Antonio visit.","officialUrl":"https://www.thealamo.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=The%20Alamo%20San%20Antonio%20TX","price":"$0 — free timed entry (est.)","photos":["assets/gulf-south/images/san-antonio-tx/attr1-1.jpg","assets/gulf-south/images/san-antonio-tx/attr1-2.jpg","assets/gulf-south/images/san-antonio-tx/attr1-3.jpg","assets/gulf-south/images/san-antonio-tx/attr1-4.jpg"]},{"name":"San Antonio River Walk","description":"Fifteen miles of shaded river paths lined with restaurants, shops, and barges, looping through downtown and out to the missions. The narrated Go Rio cruises are the classic first-timer move.","officialUrl":"https://www.theriverwalk.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=San%20Antonio%20River%20Walk%20San%20Antonio%20TX","price":"$0 — free to walk; barge cruises ~$14/person (est.)","photos":["assets/gulf-south/images/san-antonio-tx/attr2-1.jpg","assets/gulf-south/images/san-antonio-tx/attr2-2.jpg","assets/gulf-south/images/san-antonio-tx/attr2-3.jpg","assets/gulf-south/images/san-antonio-tx/attr2-4.jpg"]},{"name":"San Antonio Zoo","description":"A 50-acre zoo in Brackenridge Park with 750+ species, the Africa Live! complex, a new rhino habitat, and a beloved miniature train. Consistently ranked among Texas's best zoos.","officialUrl":"https://www.sazoo.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=San%20Antonio%20Zoo%20San%20Antonio%20TX","price":"~$35/adult, $28/child (est.)","photos":["assets/gulf-south/images/san-antonio-tx/attr3-1.jpg","assets/gulf-south/images/san-antonio-tx/attr3-2.jpg","assets/gulf-south/images/san-antonio-tx/attr3-3.jpg","assets/gulf-south/images/san-antonio-tx/attr3-4.jpg"]},{"name":"San Antonio Missions National Historical Park","description":"Four 18th-century Spanish missions — Concepción, San José, San Juan, Espada — preserved as a UNESCO World Heritage Site along the Mission Trail. Active parishes with ranger tours, all free.","officialUrl":"https://www.nps.gov/saan","mapsUrl":"https://www.google.com/maps/search/?api=1&query=San%20Antonio%20Missions%20National%20Historical%20Park%20San%20Antonio%20TX","price":"$0 — free admission (est.)","photos":["assets/gulf-south/images/san-antonio-tx/attr4-1.jpg","assets/gulf-south/images/san-antonio-tx/attr4-2.jpg","assets/gulf-south/images/san-antonio-tx/attr4-3.jpg","assets/gulf-south/images/san-antonio-tx/attr4-4.jpg"]}],"restaurants":[{"name":"Boudro's Texas Bistro","detail":"River Walk Texas bistro institution — tableside guac and prickly pear margaritas on the water.","price":"$$$"},{"name":"Rosario's","detail":"Southtown Mexican legend for puffy tacos and fish tacos on a warm patio.","price":"$$"},{"name":"The Guenther House","detail":"Historic flour-mill mansion serving beloved breakfast-for-dinner on the river terrace.","price":"$$"}],"rainyDay":["The Witte Museum — dinosaurs and Texas history in Brackenridge Park","The DoSeum — San Antonio's children's museum","San Antonio Museum of Art on the river"],"driveNotes":"San Antonio is 90 minutes south of Austin on I-35 — the two pair perfectly. Downtown is walkable, but you'll want a car for the missions (8 miles south) and the zoo. River Walk parking garages fill on weekends; the city-run lots are cheapest. Summer afternoons are brutal — do the Alamo and missions before noon.","related":["austin-tx","houston-tx","dallas-tx"],"imageAsset":"assets/gulf-south/images/san-antonio-tx/hero.jpg"},{"id":"austin-tx","title":"Austin, TX: Three-Day Family Adventure","destination":"Austin, TX","state":"TX","stateName":"Texas","region":"Hill Country","days":3,"tripType":"family adventure","interests":["family","museums","food","outdoors"],"budget":850,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Swim the springs, climb the Capitol dome, and eat your way down South Congress.","overview":"Austin is the rare capital city that feels like a playground: a free pink-granite Capitol to explore, a spring-fed pool in the middle of the city, world-class museums for Texas history and little kids, and a food scene (tacos, barbecue, queso) that never disappoints. Three days balances the big sights with Austin's famous weirdness. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Free tours of the Texas State Capitol — bigger than the US Capitol","Swimming in 68-degree Barton Springs Pool year-round","The Bullock Museum's IMAX-scale Texas story","Thinkery's hands-on exhibits for the under-10 crowd","Breakfast tacos and South Congress people-watching"],"bestSeason":"March–May; October–November","familyFriendly":"Best for ages 5+. The Capitol and Bullock are stroller-friendly; Barton Springs has a shallow end but no lifeguard-free wading for toddlers.","lat":30.26759,"lng":-97.74299,"itinerary":[{"day":1,"title":"Capitol & Springs","morning":{"stop":"Texas State Capitol","description":"Tour the 1888 pink-granite Capitol — free guided tours run every 30–45 minutes and cover the rotunda, the House and Senate chambers, and the portraits. Kids love the terrazzo floors and the sheer scale.","cost":"Free (est.)","time":"9:00 AM – 12:00 PM"},"afternoon":{"stop":"Barton Springs Pool","description":"Cool off in the 68-degree spring-fed pool in Zilker Park — three acres of clear water, a diving board, and grassy banks for picnics. It's the most Austin experience there is.","cost":"Admission ~$30 for the family (est.)","time":"1:30 PM – 4:30 PM"},"evening":{"stop":"Kerbey Lane Cafe","description":"Dinner at this Austin institution — famous for queso, pancakes all day, and a patio that welcomes families. The original Kerbey Lane location is the classic.","cost":"Dinner ~$60 for the family (est.)","time":"6:00 PM – 7:30 PM"}},{"day":2,"title":"Texas History Day","morning":{"stop":"Bullock Texas State History Museum","description":"Three floors of Texas history — from La Belle's shipwreck to oil booms to space — plus the IMAX theater and the Texas Spirit Theater's special effects. Plan 3 hours minimum.","cost":"Admission ~$44 for the family (est.)","time":"10:00 AM – 1:30 PM"},"afternoon":{"stop":"South Congress Avenue","description":"Walk SoCo: the 'I love you so much' mural, Allen's Boots, toy shops, and ice cream. It's touristy in the best way, and the street performers keep kids entertained.","cost":"Shopping and treats ~$40 (est.)","time":"2:30 PM – 5:00 PM"},"evening":{"stop":"Franklin Barbecue","description":"The pilgrimage: line up early (or order ahead) for what many call America's best brisket. Go at 4 PM on a weekday to dodge the worst of the line — the kids will survive on the smell alone.","cost":"Dinner ~$80 for the family (est.)","time":"5:00 PM – 7:00 PM"}},{"day":3,"title":"Play & Farewell","morning":{"stop":"Thinkery","description":"Austin's children's museum in Mueller — two floors of STEAM exhibits, a water play area, and the outdoor Innovators' Workshop. Best for ages 2–10; older kids head straight to the maker labs.","cost":"Admission ~$70 for the family (est.)","time":"10:00 AM – 1:00 PM"},"afternoon":{"stop":"Mueller Lake Park","description":"Picnic and playground time at the park next door, or detour to the Austin Nature & Science Center (free) in Zilker for rescued wildlife and dino digs.","cost":"Free (est.)","time":"1:30 PM – 4:00 PM"},"evening":{"stop":"Uchi","description":"One splurge: Austin's famous Japanese restaurant — the happy-hour menu (5–6:30 PM) makes it family-budget friendly, and the hot rock and tempura are kid-approved gateways.","cost":"Dinner ~$130 for the family (est.)","time":"5:30 PM – 7:30 PM"}}],"attractions":[{"name":"Texas State Capitol","description":"The 1888 pink-granite Capitol — taller than the US Capitol — with free guided tours of the rotunda, chambers, and grounds. The visitor center's exhibits and the sunset views from the south steps are bonuses.","officialUrl":"https://www.tspb.texas.gov","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Texas%20State%20Capitol%20Austin%20TX","price":"$0 — free tours (est.)","photos":["assets/gulf-south/images/austin-tx/attr1-1.jpg","assets/gulf-south/images/austin-tx/attr1-2.jpg","assets/gulf-south/images/austin-tx/attr1-3.jpg","assets/gulf-south/images/austin-tx/attr1-4.jpg"]},{"name":"Barton Springs Pool","description":"Austin's beloved 3-acre spring-fed pool in Zilker Park, a constant 68 degrees year-round. Grassy banks, a diving board, and the adjacent Zilker grounds make it the city's summer living room.","officialUrl":"https://www.austintexas.gov","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Barton%20Springs%20Pool%20Austin%20TX","price":"~$9/adult, $5/child (est.)","photos":["assets/gulf-south/images/austin-tx/attr2-1.jpg","assets/gulf-south/images/austin-tx/attr2-2.jpg","assets/gulf-south/images/austin-tx/attr2-3.jpg","assets/gulf-south/images/austin-tx/attr2-4.jpg"]},{"name":"Bullock Texas State History Museum","description":"The official Texas history museum: three floors from early exploration to the space age, the La Belle shipwreck, an IMAX theater, and the special-effects Texas Spirit Theater. The definitive Texas primer.","officialUrl":"https://www.thestoryoftexas.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Bullock%20Texas%20State%20History%20Museum%20Austin%20TX","price":"~$13/adult, $9/child (est.)","photos":["assets/gulf-south/images/austin-tx/attr3-1.jpg","assets/gulf-south/images/austin-tx/attr3-2.jpg","assets/gulf-south/images/austin-tx/attr3-3.jpg","assets/gulf-south/images/austin-tx/attr3-4.jpg"]},{"name":"Thinkery","description":"Austin's hands-on children's museum in Mueller, focused on STEAM play: water exhibits, a light lab, maker workshops, and an outdoor Innovators' Workshop. The go-to for ages 2–10.","officialUrl":"https://www.thinkeryaustin.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Thinkery%20Austin%20TX","price":"~$18.95/person (est.)","photos":["assets/gulf-south/images/austin-tx/attr4-1.jpg","assets/gulf-south/images/austin-tx/attr4-2.jpg","assets/gulf-south/images/austin-tx/attr4-3.jpg","assets/gulf-south/images/austin-tx/attr4-4.jpg"]}],"restaurants":[{"name":"Franklin Barbecue","detail":"The brisket pilgrimage — line up early or order ahead for America's most famous BBQ.","price":"$$"},{"name":"Kerbey Lane Cafe","detail":"Austin institution for queso, all-day pancakes, and family-friendly patios.","price":"$"},{"name":"Uchi","detail":"Austin's legendary Japanese spot — the happy-hour menu makes the splurge family-friendly.","price":"$$$"}],"rainyDay":["Bullock Texas State History Museum + IMAX","Thinkery children's museum","Austin Aquarium (north Austin)"],"driveNotes":"Austin is 90 minutes north of San Antonio and 3 hours south of Dallas on I-35 — pair it with San Antonio for a classic Texas week. You'll want a car, but downtown, SoCo, and Zilker are rideshare-easy. Franklin Barbecue's line starts before dawn; ordering ahead online saves hours. Summer heat is intense — swim mornings, museum afternoons.","related":["san-antonio-tx","dallas-tx","houston-tx"],"imageAsset":"assets/gulf-south/images/austin-tx/hero.jpg"},{"id":"dallas-tx","title":"Dallas, TX: Three-Day Family Adventure","destination":"Dallas, TX","state":"TX","stateName":"Texas","region":"North Texas","days":3,"tripType":"family adventure","interests":["family","museums","food","outdoors"],"budget":950,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Dinosaurs, dealeys, and deep-fried everything — Big D goes big for families.","overview":"Dallas does family trips at Texas scale: the Perot Museum's five floors of hands-on science, one of the country's top zoos, 66 acres of themed gardens at the Arboretum, and the Sixth Floor Museum's essential history. Add barbecue, Tex-Mex, and the State Fair's fall spectacle, and three days fly by. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["The Perot Museum's earthquake simulator and dinosaur hall","Dallas Zoo's Giants of the Savanna elephant habitat","The Arboretum's Rory Meyers Children's Adventure Garden","The Sixth Floor Museum's JFK history (best for ages 8+)","Brisket at Pecan Lodge in Deep Ellum"],"bestSeason":"March–May; October–November","familyFriendly":"Best for ages 6+. The Perot and Arboretum are stroller-friendly; the Sixth Floor Museum's content suits older kids best.","lat":32.77822,"lng":-96.79512,"itinerary":[{"day":1,"title":"Science Day","morning":{"stop":"Perot Museum of Nature and Science","description":"Five floors of interactive science in the Victory Park cube: the dinosaur hall, the earthquake simulator, the Moody Family Children's Museum for under-6s, and the sports-science lab. Arrive at opening and work top-down.","cost":"Admission ~$90 for the family (est.)","time":"10:00 AM – 2:00 PM"},"afternoon":{"stop":"Klyde Warren Park","description":"Walk across the street to this deck park over the freeway — food trucks, a children's playground, games, and misting fountains. The perfect decompress after the museum.","cost":"Food truck lunch ~$50 (est.)","time":"2:30 PM – 5:00 PM"},"evening":{"stop":"Pecan Lodge","description":"Deep Ellum barbecue pilgrimage — brisket, burnt ends, and the famous 'hot mess' sweet potato. Lines move fast; the picnic tables are kid-approved.","cost":"Dinner ~$85 for the family (est.)","time":"6:00 PM – 7:30 PM"}},{"day":2,"title":"Zoo & Gardens","morning":{"stop":"Dallas Zoo","description":"Morning at the 106-acre zoo: Giants of the Savanna's elephants and giraffe feeding, the Wilds of Africa monorail, and the children's zoo. The monorail gives tired legs a break.","cost":"Admission ~$54 for the family (est.)","time":"9:00 AM – 1:00 PM"},"afternoon":{"stop":"Dallas Arboretum and Botanical Garden","description":"Afternoon among 66 acres of themed gardens on White Rock Lake — and the 8-acre Rory Meyers Children's Adventure Garden, with its mist walk, treehouses, and plant-science labs.","cost":"Admission ~$90 for the family (est.)","time":"2:00 PM – 5:30 PM"},"evening":{"stop":"Ellen's","description":"Southern comfort in the West End — chicken and waffles, shrimp and grits, and a lively room that welcomes families. An easy walk from the Sixth Floor area.","cost":"Dinner ~$75 for the family (est.)","time":"6:30 PM – 8:00 PM"}},{"day":3,"title":"History & Farewell","morning":{"stop":"The Sixth Floor Museum at Dealey Plaza","description":"The essential JFK assassination museum in the former Texas School Book Depository — audio-guided, chronological, and deeply moving. Best for ages 8+; younger kids do better with the plaza and memorial outside.","cost":"Admission ~$80 for the family (est.)","time":"10:00 AM – 1:00 PM"},"afternoon":{"stop":"Reunion Tower","description":"Ride to the GeO-Deck 470 feet up for the 360-degree Dallas view and the interactive light show. The telescopes keep kids engaged while grownups spot landmarks.","cost":"Admission ~$64 for the family (est.)","time":"2:00 PM – 4:00 PM"},"evening":{"stop":"Velvet Taco","description":"Finish fun and cheap at this Dallas-born taco joint — the chicken tikka and brisket tacos are the move, and the queso is mandatory.","cost":"Dinner ~$50 for the family (est.)","time":"5:30 PM – 7:00 PM"}}],"attractions":[{"name":"Perot Museum of Nature and Science","description":"Five floors of hands-on science in an architectural landmark: dinosaur hall, earthquake simulator, children's museum, and sports-science labs. Dallas's top family attraction.","officialUrl":"https://www.perotmuseum.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Perot%20Museum%20of%20Nature%20and%20Science%20Dallas%20TX","price":"~$25/adult, $15/child (est.)","photos":["assets/gulf-south/images/dallas-tx/attr1-1.jpg","assets/gulf-south/images/dallas-tx/attr1-2.jpg","assets/gulf-south/images/dallas-tx/attr1-3.jpg","assets/gulf-south/images/dallas-tx/attr1-4.jpg"]},{"name":"Dallas Zoo","description":"A 106-acre zoo with the acclaimed Giants of the Savanna, the Wilds of Africa monorail, and a top children's zoo. One of the oldest and largest zoos in Texas.","officialUrl":"https://www.dallaszoo.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Dallas%20Zoo%20Dallas%20TX","price":"~$15/adult, $12/child (est.)","photos":["assets/gulf-south/images/dallas-tx/attr2-1.jpg","assets/gulf-south/images/dallas-tx/attr2-2.jpg","assets/gulf-south/images/dallas-tx/attr2-3.jpg","assets/gulf-south/images/dallas-tx/attr2-4.jpg"]},{"name":"Dallas Arboretum and Botanical Garden","description":"Sixty-six acres of themed gardens on White Rock Lake, plus the 8-acre Rory Meyers Children's Adventure Garden — mist walks, treehouses, and plant labs. Peak beauty in spring and fall.","officialUrl":"https://www.dallasarboretum.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Dallas%20Arboretum%20Dallas%20TX","price":"~$26/adult, $18/child (est.)","photos":["assets/gulf-south/images/dallas-tx/attr3-1.jpg","assets/gulf-south/images/dallas-tx/attr3-2.jpg","assets/gulf-south/images/dallas-tx/attr3-3.jpg","assets/gulf-south/images/dallas-tx/attr3-4.jpg"]},{"name":"The Sixth Floor Museum at Dealey Plaza","description":"The definitive JFK assassination museum on the sixth floor of the former Book Depository, with an audio-guided chronological narrative. The plaza and memorial outside are free to visit.","officialUrl":"https://www.jfk.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=The%20Sixth%20Floor%20Museum%20Dallas%20TX","price":"$24/adult, $19/youth (est.)","photos":["assets/gulf-south/images/dallas-tx/attr4-1.jpg","assets/gulf-south/images/dallas-tx/attr4-2.jpg","assets/gulf-south/images/dallas-tx/attr4-3.jpg","assets/gulf-south/images/dallas-tx/attr4-4.jpg"]}],"restaurants":[{"name":"Pecan Lodge","detail":"Deep Ellum barbecue legend — brisket, burnt ends, and the 'hot mess' sweet potato.","price":"$$"},{"name":"Ellen's","detail":"West End Southern comfort — chicken and waffles and shrimp and grits in a lively room.","price":"$$"},{"name":"Velvet Taco","detail":"Dallas-born taco joint with global flavors — chicken tikka tacos and mandatory queso.","price":"$"}],"rainyDay":["Perot Museum of Nature and Science","Dallas World Aquarium (downtown)","The Sixth Floor Museum at Dealey Plaza"],"driveNotes":"Dallas-Fort Worth is a driving metroplex — you need a car, and distances are real (the zoo to the Arboretum is 25 minutes). DART light rail connects downtown, the Perot, and Fair Park if you want to skip parking. Fall brings the State Fair of Texas (late Sept–Oct) — thrilling but crowded; book hotels early.","related":["austin-tx","houston-tx","san-antonio-tx"],"imageAsset":"assets/gulf-south/images/dallas-tx/hero.jpg"},{"id":"houston-tx","title":"Houston, TX: Three-Day Family Adventure","destination":"Houston, TX","state":"TX","stateName":"Texas","region":"Gulf Coast","days":3,"tripType":"family adventure","interests":["family","museums","food","amusement-parks"],"budget":1000,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Touch a moon rock, meet the elephants, and eat your way through America's most diverse food city.","overview":"Houston is a family-trip powerhouse: Space Center Houston's real spacecraft, a top-five zoo, a natural science museum with butterflies and dinosaurs, and one of the country's best children's museums. The Museum District clusters half the sights within walking distance, and the food — from breakfast tacos to Viet-Cajun — is a trip in itself. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Touch a real moon rock at Space Center Houston","The tram tour of NASA Johnson Space Center's working campus","Houston Zoo's African Forest elephants and sea lions","The Cockrell Butterfly Center's living rainforest","The Breakfast Klub's famous wings and waffles"],"bestSeason":"February–May; October–November","familyFriendly":"Best for ages 5+. The Museum District is stroller-friendly; Space Center Houston involves lots of walking — rent a stroller there.","lat":29.76078,"lng":-95.36952,"itinerary":[{"day":1,"title":"Space Day","morning":{"stop":"Space Center Houston","description":"Give the whole morning to the official visitor center of NASA Johnson Space Center: the flown SpaceX Falcon 9, the Apollo 17 command module, Mission Control tours via tram, and the moon rock you can actually touch.","cost":"Admission ~$120 for the family (est.)","time":"10:00 AM – 2:00 PM"},"afternoon":{"stop":"Space Center Houston","description":"Ride the tram to Rocket Park's Saturn V and the astronaut training mockups, then let the kids loose in the interactive exhibits. The tram tour is the highlight — go early before lines build.","cost":"Included with admission (est.)","time":"2:00 PM – 5:00 PM"},"evening":{"stop":"The Breakfast Klub","description":"Back in Midtown for the legendary wings and waffles — yes, for dinner. The line moves, the room buzzes, and the kids will talk about the catfish and grits.","cost":"Dinner ~$65 for the family (est.)","time":"6:30 PM – 8:00 PM"}},{"day":2,"title":"Museum District","morning":{"stop":"Houston Museum of Natural Science","description":"Start with the Morian Hall of Paleontology's dinosaurs, the Hall of Gems, and the Cockrell Butterfly Center's three-story living rainforest. The planetarium shows are worth the add-on.","cost":"Admission ~$90 for the family (est.)","time":"10:00 AM – 1:30 PM"},"afternoon":{"stop":"Houston Zoo","description":"Walk next door to the 55-acre zoo: the African Forest's chimps and rhinos, sea lion feedings, the children's zoo, and the new Galápagos Islands exhibit. The splash pad cools everyone off.","cost":"Admission ~$85 for the family (est.)","time":"2:00 PM – 5:30 PM"},"evening":{"stop":"Hugo's","description":"Upscale-but-welcoming regional Mexican in Montrose — the wood-grilled meats and chile rellenos are the draw. Book ahead; it's a Houston special-occasion staple that loves families.","cost":"Dinner ~$110 for the family (est.)","time":"6:30 PM – 8:30 PM"}},{"day":3,"title":"Kids' Day","morning":{"stop":"Children's Museum Houston","description":"One of America's best children's museums: the 10,000-square-foot Kidtropolis mini-city, the water-play FlowWorks, and the outdoor EcoStation. Plan 3–4 hours; kids won't want to leave.","cost":"Admission ~$60 for the family (est.)","time":"10:00 AM – 2:00 PM"},"afternoon":{"stop":"Hermann Park","description":"Picnic in Hermann Park, ride the miniature train, paddle the lake, and visit the free McGovern Centennial Gardens. The park is the Museum District's green heart.","cost":"Train ~$14 for the family (est.)","time":"2:30 PM – 5:00 PM"},"evening":{"stop":"Pappas Bros. Steakhouse","description":"The Texas splurge: dry-aged steaks, legendary service, and a kids' menu that doesn't phone it in. The Galleria location is the classic.","cost":"Dinner ~$200 for the family (est.)","time":"6:30 PM – 8:30 PM"}}],"attractions":[{"name":"Space Center Houston","description":"The official visitor center of NASA Johnson Space Center, with flown spacecraft, a touchable moon rock, Mission Control tram tours, and Rocket Park's Saturn V. The definitive space experience in Texas.","officialUrl":"https://www.spacecenter.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Space%20Center%20Houston%20Houston%20TX","price":"From $30/adult, $25/child (est.)","photos":["assets/gulf-south/images/houston-tx/attr1-1.jpg","assets/gulf-south/images/houston-tx/attr1-2.jpg","assets/gulf-south/images/houston-tx/attr1-3.jpg","assets/gulf-south/images/houston-tx/attr1-4.jpg"]},{"name":"Houston Zoo","description":"A 55-acre zoo in Hermann Park with the African Forest, the new Galápagos Islands habitat, sea lions, and a beloved children's zoo. One of the most-visited zoos in the nation.","officialUrl":"https://www.houstonzoo.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Houston%20Zoo%20Houston%20TX","price":"~$24/adult, $18/child (est.)","photos":["assets/gulf-south/images/houston-tx/attr2-1.jpg","assets/gulf-south/images/houston-tx/attr2-2.jpg","assets/gulf-south/images/houston-tx/attr2-3.jpg","assets/gulf-south/images/houston-tx/attr2-4.jpg"]},{"name":"Houston Museum of Natural Science","description":"One of the country's most-visited natural history museums: dinosaur halls, the Cockrell Butterfly Center's living rainforest, gems and minerals, and a planetarium. The Museum District's anchor.","officialUrl":"https://www.hmns.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Houston%20Museum%20of%20Natural%20Science%20Houston%20TX","price":"$25/adult, $15/child (est.)","photos":["assets/gulf-south/images/houston-tx/attr3-1.jpg","assets/gulf-south/images/houston-tx/attr3-2.jpg","assets/gulf-south/images/houston-tx/attr3-3.jpg","assets/gulf-south/images/houston-tx/attr3-4.jpg"]},{"name":"Children's Museum Houston","description":"Consistently rated America's best children's museum: Kidtropolis's kid-sized city, FlowWorks water play, the outdoor EcoStation, and maker labs. A full half-day for ages 2–12.","officialUrl":"https://www.cmhouston.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Children%27s%20Museum%20Houston%20Houston%20TX","price":"~$15/person (est.)","photos":["assets/gulf-south/images/houston-tx/attr4-1.jpg","assets/gulf-south/images/houston-tx/attr4-2.jpg","assets/gulf-south/images/houston-tx/attr4-3.jpg","assets/gulf-south/images/houston-tx/attr4-4.jpg"]}],"restaurants":[{"name":"The Breakfast Klub","detail":"Midtown legend for wings and waffles and catfish and grits — worth the line.","price":"$$"},{"name":"Pappas Bros. Steakhouse","detail":"Texas's temple of dry-aged steak with legendary service — the big splurge.","price":"$$$"},{"name":"Hugo's","detail":"Montrose regional Mexican — wood-grilled meats and chile rellenos in a warm room.","price":"$$$"}],"rainyDay":["Houston Museum of Natural Science + planetarium","Children's Museum Houston","Downtown Aquarium (downtown)"],"driveNotes":"Houston is vast — you need a car, and Space Center Houston is 25 miles south of downtown. The Museum District (zoo, HMNS, children's museum, Hermann Park) clusters beautifully; park once and walk. Summer is brutally hot and humid; do outdoor stops before 11 AM. I-45 construction is perpetual — allow extra time.","related":["san-antonio-tx","dallas-tx","austin-tx"],"imageAsset":"assets/gulf-south/images/houston-tx/hero.jpg"},{"id":"big-bend-tx","title":"Big Bend, TX: Four-Day Desert Adventure","destination":"Big Bend, TX","state":"TX","stateName":"Texas","region":"West Texas","days":4,"tripType":"desert adventure","interests":["family","outdoors","nature","scenic"],"budget":750,"budgetNote":"For 2 adults + 2 kids: park fees, meals, and gas; lodging not included.","tagline":"Canyons, dark skies, and a ghost town — Texas's wildest corner rewards the drive.","overview":"Big Bend is the most remote national park in the Lower 48 — and one of the most spectacular. Towering desert canyons, natural hot springs on the Rio Grande, the Chisos Mountains, and some of America's darkest night skies pack four days easily. Come for the landscapes; stay for the stars, the ghost town of Terlingua, and the feeling of the frontier. Note: the Chisos Basin lodge restaurant is currently closed (a food truck serves the area) — plan meals accordingly. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Soaking in the riverside Hot Springs at sunset","The Santa Elena Canyon trail between 1,500-foot walls","Milky Way skies — among the darkest in North America","Terlingua's ghost-town porches and the Starlight Theatre","The Window View sunset in the Chisos Basin"],"bestSeason":"October–April","familyFriendly":"Best for ages 6+. Desert heat is dangerous May–September — visit in cooler months, carry 1 gallon of water per person per day, and stick to short trails with kids.","lat":29.3282,"lng":-103.20614,"itinerary":[{"day":1,"title":"Into the Park","morning":{"stop":"Big Bend National Park","description":"Enter via the north (Marathon) or west (Study Butte) entrance — it's a long drive in, so fuel up. Stop at the Panther Junction visitor center for maps, junior ranger books, and the park film.","cost":"Park entry $30/vehicle, good for 7 days (est.)","time":"9:00 AM – 11:00 AM"},"afternoon":{"stop":"Chisos Basin","description":"Drive the winding road up into the Chisos Mountains. Hike the easy Window View Trail, explore the basin amphitheater, and watch for javelinas and roadrunners. The lodge area has the food truck and a camp store.","cost":"Included with park entry (est.)","time":"12:00 PM – 4:30 PM"},"evening":{"stop":"Chisos Basin","description":"Stay for the famous Window sunset — the sun drops through the V-notch in the mountains. Then look up: the Milky Way appears with shocking clarity. Bring jackets; desert nights are cold.","cost":"Free (est.)","time":"6:00 PM – 9:00 PM"}},{"day":2,"title":"Canyon Day","morning":{"stop":"Santa Elena Canyon","description":"Drive the Ross Maxwell Scenic Drive to the canyon mouth. The 1.7-mile round-trip trail crosses Terlingua Creek and climbs into the canyon between 1,500-foot limestone walls — the park's signature hike, doable for kids.","cost":"Included with park entry (est.)","time":"8:30 AM – 12:00 PM"},"afternoon":{"stop":"Hot Springs Historic District","description":"Drive east to the riverside hot springs: a short trail past the old bathhouse ruins leads to the 105-degree foundation pool right on the Rio Grande. Soak with Mexico across the river.","cost":"Included with park entry (est.)","time":"2:00 PM – 5:00 PM"},"evening":{"stop":"Terlingua Ghost Town","description":"Head to the ghost town for dinner at the Starlight Theatre — live music, a famous porch, and chili under the desert sky. Browse the ruins and shops at golden hour first.","cost":"Dinner ~$80 for the family (est.)","time":"6:30 PM – 9:00 PM"}},{"day":3,"title":"Ghost Town & River","morning":{"stop":"Terlingua Ghost Town","description":"Explore the mining ruins in morning light: the company store, the cemetery on the hill, and the art galleries in old adobe buildings. The Trading Company has the best souvenirs.","cost":"Free to explore (est.)","time":"9:00 AM – 12:00 PM"},"afternoon":{"stop":"Big Bend Ranch State Park","description":"Drive the scenic FM 170 river road west — Texas's most beautiful drive — into Big Bend Ranch State Park. Stop at the Closed Canyon trail (1.4 miles round-trip) for a slot-canyon scramble kids love.","cost":"State park day-use ~$5/person (est.)","time":"1:00 PM – 5:00 PM"},"evening":{"stop":"La Kiva Restaurant & Bar","description":"Dinner in Terlingua's famous underground bar-restaurant — part cave, part cantina. Burgers, steaks, and live music in the most atmospheric room in West Texas.","cost":"Dinner ~$75 for the family (est.)","time":"6:30 PM – 9:00 PM"}},{"day":4,"title":"Desert Morning & Stars","morning":{"stop":"Chisos Basin","description":"Return to the basin for the Lost Mine Trail's first mile (great views, kid-doable) or the Basin Loop. Fill water bottles, say goodbye to the javelinas, and start the long drive out by noon.","cost":"Included with park entry (est.)","time":"8:00 AM – 11:30 AM"},"afternoon":{"stop":"Marathon","description":"Stop in Marathon on the way out — the Gage Hotel's gardens, the tiny shops, and lunch before the long highway stretch. It's the last real town for hours.","cost":"Lunch ~$55 for the family (est.)","time":"1:00 PM – 2:30 PM"},"evening":{"stop":"Long Draw Pizza","description":"If you're overnighting in Lajitas or Study Butte, finish with wood-fired pizza at Long Draw — the locals' favorite, with a patio made for desert sunsets.","cost":"Dinner ~$60 for the family (est.)","time":"6:00 PM – 8:00 PM"}}],"attractions":[{"name":"Santa Elena Canyon","description":"Big Bend's signature canyon, where the Rio Grande cuts 1,500-foot limestone walls. The 1.7-mile round-trip trail into the canyon mouth is the park's classic family hike — dramatic, shaded, and unforgettable.","officialUrl":"https://www.nps.gov/bibe","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Santa%20Elena%20Canyon%20Big%20Bend%20TX","price":"$0 — included with $30/vehicle park entry (est.)","photos":["assets/gulf-south/images/big-bend-tx/attr1-1.jpg","assets/gulf-south/images/big-bend-tx/attr1-2.jpg","assets/gulf-south/images/big-bend-tx/attr1-3.jpg","assets/gulf-south/images/big-bend-tx/attr1-4.jpg"]},{"name":"Hot Springs Historic District","description":"A short trail past 1900s bathhouse ruins leads to a 105-degree natural hot spring pool on the banks of the Rio Grande. Soak at sunset with Mexico across the river — the park's most magical spot.","officialUrl":"https://www.nps.gov/bibe","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Hot%20Springs%20Historic%20District%20Big%20Bend%20TX","price":"$0 — included with park entry (est.)","photos":["assets/gulf-south/images/big-bend-tx/attr2-1.jpg","assets/gulf-south/images/big-bend-tx/attr2-2.jpg","assets/gulf-south/images/big-bend-tx/attr2-3.jpg","assets/gulf-south/images/big-bend-tx/attr2-4.jpg"]},{"name":"Terlingua Ghost Town","description":"The atmospheric ruins of a mercury-mining boomtown, now a community of artists, musicians, and desert rats. Adobe ruins, the hilltop cemetery, galleries, and the famous Starlight Theatre porch.","officialUrl":"https://www.ghosttowntexas.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Terlingua%20Ghost%20Town%20Terlingua%20TX","price":"$0 — free to explore (est.)","photos":["assets/gulf-south/images/big-bend-tx/attr3-1.jpg","assets/gulf-south/images/big-bend-tx/attr3-2.jpg","assets/gulf-south/images/big-bend-tx/attr3-3.jpg","assets/gulf-south/images/big-bend-tx/attr3-4.jpg"]},{"name":"Chisos Basin","description":"The mountain heart of the park, ringed by the Chisos peaks: the Window View sunset, the Lost Mine and Basin Loop trails, javelina sightings, and trailheads for the park's best day hikes.","officialUrl":"https://www.nps.gov/bibe","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Chisos%20Basin%20Big%20Bend%20TX","price":"$0 — included with park entry (est.)","photos":["assets/gulf-south/images/big-bend-tx/attr4-1.jpg","assets/gulf-south/images/big-bend-tx/attr4-2.jpg","assets/gulf-south/images/big-bend-tx/attr4-3.jpg","assets/gulf-south/images/big-bend-tx/attr4-4.jpg"]}],"restaurants":[{"name":"Starlight Theatre Restaurant & Bar","detail":"Terlingua's legendary porch — live music, famous chili, and desert sunsets.","price":"$$"},{"name":"La Kiva Restaurant & Bar","detail":"Terlingua's underground cave-cantina — burgers and steaks in the most atmospheric room in West Texas.","price":"$$"},{"name":"Long Draw Pizza","detail":"Lajitas wood-fired pizza with a patio made for desert sunsets — the locals' favorite.","price":"$"}],"rainyDay":["Panther Junction visitor center exhibits and park film","Big Bend Ranch State Park's Barton Warnock Visitor Center","Terlingua's galleries and the Starlight Theatre porch"],"driveNotes":"Big Bend is remote — 6+ hours from Austin or San Antonio, with the nearest real grocery in Alpine (80 miles north). Fill gas at every opportunity; carry 1 gallon of water per person per day. The Chisos Basin road is winding but paved; RVs over 24 feet are restricted. Book lodging 6+ months ahead for spring break and holidays.","related":["san-antonio-tx","white-sands-nm","carlsbad-nm"],"imageAsset":"assets/gulf-south/images/big-bend-tx/hero.jpg"},{"id":"santa-fe-nm","title":"Santa Fe, NM: Three-Day Art & Adobe Getaway","destination":"Santa Fe, NM","state":"NM","stateName":"New Mexico","region":"North Central New Mexico","days":3,"tripType":"art & culture getaway","interests":["family","museums","food","historical-sites"],"budget":900,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"America's oldest capital — where adobe, art, and green chile make magic.","overview":"Santa Fe is the oldest state capital in America, and it doesn't look like anywhere else: adobe streets, a 400-year-old plaza, world-class art museums, and the mind-bending Meow Wolf. Kids love the interactive art, the plaza's Native artisans, and the sheer novelty of the place — grownups get the galleries and the food. Three days balances culture, play, and great eating. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Meow Wolf's House of Eternal Return — part art, part mystery, all wow","Native artisans selling jewelry under the Palace of the Governors portal","The Georgia O'Keeffe Museum's desert-inspired masterpieces","Loretto Chapel's Miraculous Staircase legend","Green chile everything — start with breakfast burritos"],"bestSeason":"April–June; September–October","familyFriendly":"Best for ages 6+. The Plaza is flat and stroller-friendly; Meow Wolf is sensory-intense — younger kids may find parts overwhelming.","lat":35.69177,"lng":-105.93824,"itinerary":[{"day":1,"title":"Plaza & Chapel","morning":{"stop":"Santa Fe Plaza","description":"Start at the historic Plaza — browse the Native American artisans under the Palace of the Governors portal, visit the New Mexico History Museum's Palace, and let the kids climb the plaza's old cottonwood-shaded benches. Everything is within a few blocks.","cost":"Free to explore; museum ~$36 for the family (est.)","time":"9:30 AM – 12:30 PM"},"afternoon":{"stop":"Loretto Chapel","description":"Walk to the 1878 Gothic chapel to see the famous Miraculous Staircase — a helix with no visible support that legend says St. Joseph built. The small museum covers the Sisters of Loretto's story.","cost":"Admission ~$20 for the family (est.)","time":"1:30 PM – 3:00 PM"},"evening":{"stop":"The Shed","description":"Dinner at this Santa Fe institution — red and green chile enchiladas in a 300-year-old hacienda. Get both ('Christmas') and thank us later. Book ahead; it's beloved.","cost":"Dinner ~$85 for the family (est.)","time":"6:00 PM – 8:00 PM"}},{"day":2,"title":"O'Keeffe & Canyon Road","morning":{"stop":"Georgia O'Keeffe Museum","description":"Tour the museum devoted to America's most famous desert painter — her flowers, skulls, and New Mexico landscapes. The family guides turn the galleries into a scavenger hunt for kids.","cost":"Admission ~$70 for the family (est.)","time":"10:00 AM – 12:30 PM"},"afternoon":{"stop":"Canyon Road","description":"Stroll the half-mile of galleries along Canyon Road — sculpture gardens, Native art, and contemporary spaces. Many galleries welcome kids; the outdoor sculptures are the real playground.","cost":"Free to browse (est.)","time":"1:30 PM – 4:30 PM"},"evening":{"stop":"Café Pasqual's","description":"Dinner at this beloved downtown café — organic New Mexican with global twists, communal tables, and legendary breakfast (they do dinner too). The chile is serious.","cost":"Dinner ~$95 for the family (est.)","time":"6:00 PM – 8:00 PM"}},{"day":3,"title":"Meow Wolf Day","morning":{"stop":"Meow Wolf Santa Fe","description":"Give the whole morning to the House of Eternal Return — a Victorian house that opens into 70+ rooms of interactive, climb-through art. Solve the mystery, crawl through the dryer into another dimension, and get happily lost.","cost":"Admission ~$110 for the family (est.)","time":"10:00 AM – 1:30 PM"},"afternoon":{"stop":"Meow Wolf Santa Fe","description":"Keep exploring — most families need 3–4 hours. The gift shop is dangerously fun. Afterward, decompress at the nearby Railyard's park and farmers market (weekends).","cost":"Snacks ~$30 (est.)","time":"1:30 PM – 4:00 PM"},"evening":{"stop":"Tomasita's","description":"Farewell dinner at this Railyard-area New Mexican staple — huge portions, strong margaritas, and the sopaipillas with honey that kids inhale.","cost":"Dinner ~$65 for the family (est.)","time":"6:00 PM – 7:30 PM"}}],"attractions":[{"name":"Santa Fe Plaza","description":"The 400-year-old heart of Santa Fe, ringed by adobe landmarks including the Palace of the Governors — where Native artisans sell jewelry under the portal — plus the cathedral, shops, and the Plaza's bandstand concerts.","officialUrl":"https://www.santafenm.gov","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Santa%20Fe%20Plaza%20Santa%20Fe%20NM","price":"$0 — free to explore (est.)","photos":["assets/gulf-south/images/santa-fe-nm/attr1-1.jpg","assets/gulf-south/images/santa-fe-nm/attr1-2.jpg","assets/gulf-south/images/santa-fe-nm/attr1-3.jpg","assets/gulf-south/images/santa-fe-nm/attr1-4.jpg"]},{"name":"Georgia O'Keeffe Museum","description":"The world's largest collection of O'Keeffe's work — her iconic flowers, New Mexico landscapes, and desert bones — in an intimate downtown museum. Family guides and art-making programs welcome kids.","officialUrl":"https://www.okeeffemuseum.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Georgia%20O%27Keeffe%20Museum%20Santa%20Fe%20NM","price":"$22/adult, $12/child (est.)","photos":["assets/gulf-south/images/santa-fe-nm/attr2-1.jpg","assets/gulf-south/images/santa-fe-nm/attr2-2.jpg","assets/gulf-south/images/santa-fe-nm/attr2-3.jpg","assets/gulf-south/images/santa-fe-nm/attr2-4.jpg"]},{"name":"Meow Wolf Santa Fe","description":"The House of Eternal Return: a 20,000-square-foot immersive art experience — a Victorian house hiding portals to alien worlds, secret passages, and a mystery to solve. Part gallery, part playground, entirely unique.","officialUrl":"https://www.meowwolf.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Meow%20Wolf%20Santa%20Fe%20NM","price":"~$32/adult, $24/child (est.)","photos":["assets/gulf-south/images/santa-fe-nm/attr3-1.jpg","assets/gulf-south/images/santa-fe-nm/attr3-2.jpg","assets/gulf-south/images/santa-fe-nm/attr3-3.jpg","assets/gulf-south/images/santa-fe-nm/attr3-4.jpg"]},{"name":"Loretto Chapel","description":"The 1878 Gothic chapel famous for its Miraculous Staircase — a spiral helix built with no visible support, attributed by legend to St. Joseph. A quick, memorable stop near the Plaza.","officialUrl":"https://www.lorettochapel.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Loretto%20Chapel%20Santa%20Fe%20NM","price":"~$5/person (est.)","photos":["assets/gulf-south/images/santa-fe-nm/attr4-1.jpg","assets/gulf-south/images/santa-fe-nm/attr4-2.jpg","assets/gulf-south/images/santa-fe-nm/attr4-3.jpg","assets/gulf-south/images/santa-fe-nm/attr4-4.jpg"]}],"restaurants":[{"name":"The Shed","detail":"Santa Fe institution in a 300-year-old hacienda — red and green chile enchiladas done right.","price":"$$"},{"name":"Café Pasqual's","detail":"Beloved downtown café with organic New Mexican-global cooking and legendary breakfasts.","price":"$$"},{"name":"Tomasita's","detail":"Railyard-area New Mexican staple — huge portions, strong margaritas, honey sopaipillas.","price":"$"}],"rainyDay":["Meow Wolf Santa Fe — a full rainy day on its own","New Mexico History Museum at the Palace of the Governors","Museum of International Folk Art on Museum Hill"],"driveNotes":"Santa Fe is 1 hour north of Albuquerque on I-25 — fly into ABQ and drive up. Downtown is walkable; park at your hotel and use the free Santa Fe Pickup shuttle or walk everywhere. At 7,000 feet, altitude affects some visitors — hydrate, take it easy day one, and wear sunscreen. Meow Wolf and popular restaurants book out; reserve ahead.","related":["albuquerque-nm","taos-nm","white-sands-nm"],"imageAsset":"assets/gulf-south/images/santa-fe-nm/hero.jpg"},{"id":"albuquerque-nm","title":"Albuquerque, NM: Three-Day Family Adventure","destination":"Albuquerque, NM","state":"NM","stateName":"New Mexico","region":"Central New Mexico","days":3,"tripType":"family adventure","interests":["family","outdoors","museums","scenic"],"budget":800,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Balloons, a tramway to 10,000 feet, and 300 years of adobe — the Duke City delivers.","overview":"Albuquerque packs a remarkable family trip: the BioPark's zoo-aquarium-gardens combo, the world's longest aerial tram to a mountain summit, the 300-year-old adobe of Old Town, and Pueblo culture at the Indian Pueblo Cultural Center. October's Balloon Fiesta is bucket-list — but any season works. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Riding the Sandia Peak Tramway 2.7 miles up the mountain","The BioPark's zoo, aquarium, botanic garden, and Tingley Beach — one ticket","Old Town's adobe plaza, San Felipe church, and candy shops","Pueblo dances and fry bread at the Indian Pueblo Cultural Center","Sunset over the Sandias — the watermelon mountains"],"bestSeason":"April–June; September–October","familyFriendly":"Best for ages 5+. The BioPark and Old Town are stroller-friendly; the tramway is smooth but the summit is 10,378 feet — bring jackets year-round.","lat":35.08423,"lng":-106.64905,"itinerary":[{"day":1,"title":"BioPark Day","morning":{"stop":"ABQ BioPark","description":"Start at the Zoo: elephants, polar bears, and the Africa and Asia exhibits. The BioPark's combo ticket covers the zoo, aquarium, botanic garden, and Tingley Beach — plan the zoo for the cool morning hours.","cost":"Combo admission ~$60 for the family (est.)","time":"9:00 AM – 1:00 PM"},"afternoon":{"stop":"ABQ BioPark","description":"Cross to the Aquarium's shark tank and the Botanic Garden's BUGarium and Japanese garden. Ride the narrow-gauge train between the zoo and the gardens — kids love it.","cost":"Train ~$12 for the family (est.)","time":"1:30 PM – 5:00 PM"},"evening":{"stop":"Frontier Restaurant","description":"The classic post-BioPark dinner — this Route 66 institution serves legendary green chile cheeseburgers and breakfast burritos at student prices. The tortilla-making window mesmerizes kids.","cost":"Dinner ~$45 for the family (est.)","time":"6:00 PM – 7:30 PM"}},{"day":2,"title":"Tramway & Old Town","morning":{"stop":"Sandia Peak Tramway","description":"Ride the 2.7-mile tram — one of the world's longest — from the desert floor to the 10,378-foot summit. Hike the short Crest Trail, spot the city below, and have hot chocolate at the mountaintop restaurant.","cost":"Tram ~$110 for the family (est.)","time":"9:30 AM – 1:00 PM"},"afternoon":{"stop":"Old Town Albuquerque","description":"Wander the 1706 adobe plaza: San Felipe de Neri Church, 150+ shops and galleries, the Rattlesnake Museum (kids' favorite), and candy shops. Street musicians and artisans fill the plaza.","cost":"Rattlesnake Museum ~$20 for the family (est.)","time":"2:00 PM – 5:00 PM"},"evening":{"stop":"El Pinto","description":"Dinner at this North Valley New Mexican landmark — famous for its salsas, chile rellenos, and a patio under 100-year-old cottonwoods. The sopaipillas arrive warm and endless.","cost":"Dinner ~$85 for the family (est.)","time":"6:00 PM – 8:00 PM"}},{"day":3,"title":"Pueblo Culture","morning":{"stop":"Indian Pueblo Cultural Center","description":"Learn the stories of New Mexico's 19 Pueblos through the museum's exhibits, then watch the traditional dance performances (weekends) in the courtyard. The artists' demonstrations — pottery, jewelry — fascinate kids.","cost":"Admission ~$40 for the family (est.)","time":"10:00 AM – 1:00 PM"},"afternoon":{"stop":"Indian Pueblo Cultural Center","description":"Lunch at the Pueblo Harvest restaurant — Indigenous foods like bison, blue corn, and green chile stew. Browse the museum shop for authentic Pueblo art before leaving.","cost":"Lunch ~$55 for the family (est.)","time":"1:00 PM – 3:00 PM"},"evening":{"stop":"Sadie's of New Mexico","description":"Farewell dinner at this Albuquerque institution — the salsa bar alone is worth it, and the stuffed sopaipillas are the move. Loud, fun, and family-perfect.","cost":"Dinner ~$70 for the family (est.)","time":"5:30 PM – 7:30 PM"}}],"attractions":[{"name":"ABQ BioPark","description":"Albuquerque's biological park: zoo, aquarium, botanic garden, and Tingley Beach on one combo ticket, linked by a narrow-gauge train. Elephants, polar bears, shark tanks, and the magical BUGarium.","officialUrl":"https://www.cabq.gov/artsculture/biopark","mapsUrl":"https://www.google.com/maps/search/?api=1&query=ABQ%20BioPark%20Albuquerque%20NM","price":"~$19.50/adult, ~$11/child (est.)","photos":["assets/gulf-south/images/albuquerque-nm/attr1-1.jpg","assets/gulf-south/images/albuquerque-nm/attr1-2.jpg","assets/gulf-south/images/albuquerque-nm/attr1-3.jpg","assets/gulf-south/images/albuquerque-nm/attr1-4.jpg"]},{"name":"Sandia Peak Tramway","description":"One of the world's longest aerial trams, rising 2.7 miles from the desert to the 10,378-foot Sandia summit. Ski runs, hiking trails, and a mountaintop restaurant await at the top.","officialUrl":"https://www.sandiapeak.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Sandia%20Peak%20Tramway%20Albuquerque%20NM","price":"$35/adult, $25/child round-trip (est.)","photos":["assets/gulf-south/images/albuquerque-nm/attr2-1.jpg","assets/gulf-south/images/albuquerque-nm/attr2-2.jpg","assets/gulf-south/images/albuquerque-nm/attr2-3.jpg","assets/gulf-south/images/albuquerque-nm/attr2-4.jpg"]},{"name":"Old Town Albuquerque","description":"The 1706 adobe heart of the city: San Felipe de Neri Church, a shady plaza, 150+ shops and galleries, the Rattlesnake Museum, and street performers. The city's most atmospheric stroll.","officialUrl":"https://www.albuquerqueoldtown.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Old%20Town%20Albuquerque%20NM","price":"$0 — free to explore (est.)","photos":["assets/gulf-south/images/albuquerque-nm/attr3-1.jpg","assets/gulf-south/images/albuquerque-nm/attr3-2.jpg","assets/gulf-south/images/albuquerque-nm/attr3-3.jpg","assets/gulf-south/images/albuquerque-nm/attr3-4.jpg"]},{"name":"Indian Pueblo Cultural Center","description":"The gateway to New Mexico's 19 Pueblos: museum exhibits, weekend traditional dances, artist demonstrations, and the Pueblo Harvest restaurant serving Indigenous cuisine. Essential and moving.","officialUrl":"https://www.indianpueblo.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Indian%20Pueblo%20Cultural%20Center%20Albuquerque%20NM","price":"~$12/adult, $8/child (est.)","photos":["assets/gulf-south/images/albuquerque-nm/attr4-1.jpg","assets/gulf-south/images/albuquerque-nm/attr4-2.jpg","assets/gulf-south/images/albuquerque-nm/attr4-3.jpg","assets/gulf-south/images/albuquerque-nm/attr4-4.jpg"]}],"restaurants":[{"name":"Frontier Restaurant","detail":"Route 66 institution — legendary green chile cheeseburgers and breakfast burritos at student prices.","price":"$"},{"name":"El Pinto","detail":"North Valley New Mexican landmark — famous salsas, chile rellenos, cottonwood-shaded patio.","price":"$$"},{"name":"Sadie's of New Mexico","detail":"Albuquerque institution — salsa bar, stuffed sopaipillas, loud and family-perfect.","price":"$$"}],"rainyDay":["ABQ BioPark Aquarium and Botanic Garden conservatory","New Mexico Museum of Natural History & Science","Indian Pueblo Cultural Center"],"driveNotes":"Albuquerque is the state's travel hub — fly in, rent a car, and day-trip to Santa Fe (1 hour) or the tramway (20 minutes from downtown). The city is easy to navigate on the I-25/I-40 grid. October's Balloon Fiesta books everything a year out; any other month is relaxed. Altitude is 5,300 feet — hydrate.","related":["santa-fe-nm","taos-nm","white-sands-nm"],"imageAsset":"assets/gulf-south/images/albuquerque-nm/hero.jpg"},{"id":"taos-nm","title":"Taos, NM: Three-Day High Desert Escape","destination":"Taos, NM","state":"NM","stateName":"New Mexico","region":"North Central New Mexico","days":3,"tripType":"desert escape","interests":["family","historical-sites","scenic","museums"],"budget":700,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"A thousand-year-old pueblo, a 650-foot gorge, and art around every adobe corner.","overview":"Taos is high-desert magic: the multi-storied adobe of Taos Pueblo (continuously inhabited for 1,000+ years), the dizzying Rio Grande Gorge Bridge, a century of art history, and the off-grid Earthships. It's smaller and mellower than Santa Fe — 70 miles north — and kids remember it forever. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Taos Pueblo — the iconic North House, still home to 150 residents","Walking the Rio Grande Gorge Bridge 650 feet above the river","The Harwood Museum's Taos Society of Artists collection","Touring an off-grid Earthship — kids love the bottle walls","Ski Valley's summer scenic chairlift and alpine slide"],"bestSeason":"May–October","familyFriendly":"Best for ages 6+. Taos Pueblo involves uneven ground and ladders (climb only where invited); the gorge bridge is fenced but vertigo-inducing.","lat":36.41202,"lng":-105.57412,"itinerary":[{"day":1,"title":"Pueblo Day","morning":{"stop":"Taos Pueblo","description":"Tour the UNESCO World Heritage pueblo with a resident guide — the 1,000-year-old Hlauuma (North House), the San Geronimo church ruins, and the artists' shops. Buy fry bread from the vendors and respect the no-photography zones.","cost":"Admission ~$80 for the family (est.)","time":"9:30 AM – 1:00 PM"},"afternoon":{"stop":"Taos Plaza","description":"Lunch and browsing on the historic plaza — galleries, the Kit Carson Home & Museum, and ice cream. The plaza's shops are a gentle afternoon after the pueblo's intensity.","cost":"Lunch ~$50 for the family (est.)","time":"1:30 PM – 4:30 PM"},"evening":{"stop":"Orlando's New Mexican Cafe","description":"Dinner at this local favorite — classic New Mexican plates, strong margaritas, and a patio. The green chile chicken enchiladas are the order.","cost":"Dinner ~$65 for the family (est.)","time":"6:00 PM – 7:30 PM"}},{"day":2,"title":"Gorge & Art","morning":{"stop":"Rio Grande Gorge Bridge","description":"Drive 10 miles west to the 'High Bridge' — 650 feet above the Rio Grande. Walk the pedestrian path (fenced, but thrilling), watch for bighorn sheep on the West Rim Trail, and picnic at the rest area.","cost":"Free (est.)","time":"9:00 AM – 12:00 PM"},"afternoon":{"stop":"Harwood Museum of Art","description":"Back in town for the Harwood — the Taos Society of Artists, Agnes Martin, and the historic Burch house. Small, beautiful, and digestible in 90 minutes with kids.","cost":"Admission ~$45 for the family (est.)","time":"1:30 PM – 3:30 PM"},"evening":{"stop":"The Love Apple","description":"The special dinner: farm-to-table in a 200-year-old adobe chapel north of town. The menu changes with the seasons; the setting is unforgettable. Book ahead.","cost":"Dinner ~$140 for the family (est.)","time":"6:30 PM – 8:30 PM"}},{"day":3,"title":"Earthships & Farewell","morning":{"stop":"Earthship Visitor Center","description":"Tour the off-grid Earthship community — homes built from tires, bottles, and cans that grow their own food and catch their own water. The self-guided tour's greenhouse hallways amaze kids.","cost":"Admission ~$30 for the family (est.)","time":"10:00 AM – 12:30 PM"},"afternoon":{"stop":"Taos Ski Valley","description":"Drive 20 minutes up to the ski valley — in summer, ride the scenic chairlift and the alpine slide; in winter, it's a top family ski mountain. Lunch at the base area.","cost":"Chairlift ~$60 for the family (est.)","time":"1:00 PM – 4:30 PM"},"evening":{"stop":"Michael's Kitchen","description":"Farewell at this Taos institution — famous for its pastries, New Mexican plates, and all-day breakfast. The cinnamon rolls are the take-home order.","cost":"Dinner ~$60 for the family (est.)","time":"6:00 PM – 7:30 PM"}}],"attractions":[{"name":"Taos Pueblo","description":"A UNESCO World Heritage Site and one of America's oldest continuously inhabited communities — the multi-storied adobe Hlauuma, resident-guided tours, artists' shops, and fry bread vendors. Profound and beautiful.","officialUrl":"https://www.taospueblo.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Taos%20Pueblo%20Taos%20NM","price":"$25/adult, $15/child (est.)","photos":["assets/gulf-south/images/taos-nm/attr1-1.jpg","assets/gulf-south/images/taos-nm/attr1-2.jpg","assets/gulf-south/images/taos-nm/attr1-3.jpg","assets/gulf-south/images/taos-nm/attr1-4.jpg"]},{"name":"Rio Grande Gorge Bridge","description":"The 'High Bridge' on US 64 — a steel arch 650 feet above the Rio Grande, with fenced pedestrian walkways, observation platforms, and the West Rim Trail. The gorge views are staggering.","officialUrl":"https://www.blm.gov/visit/rgdnnm","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Rio%20Grande%20Gorge%20Bridge%20Taos%20NM","price":"$0 — free (est.)","photos":["assets/gulf-south/images/taos-nm/attr2-1.jpg","assets/gulf-south/images/taos-nm/attr2-2.jpg","assets/gulf-south/images/taos-nm/attr2-3.jpg","assets/gulf-south/images/taos-nm/attr2-4.jpg"]},{"name":"Harwood Museum of Art","description":"The University of New Mexico's Taos art museum: the Taos Society of Artists, Hispanic devotional art, Agnes Martin, and contemporary work in a historic adobe complex. Intimate and excellent.","officialUrl":"https://www.harwoodmuseum.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Harwood%20Museum%20of%20Art%20Taos%20NM","price":"~$15/adult, $8/child (est.)","photos":["assets/gulf-south/images/taos-nm/attr3-1.jpg","assets/gulf-south/images/taos-nm/attr3-2.jpg","assets/gulf-south/images/taos-nm/attr3-3.jpg","assets/gulf-south/images/taos-nm/attr3-4.jpg"]},{"name":"Earthship Visitor Center","description":"The flagship of the Greater World Earthship Community — self-guided tours through off-grid homes built from recycled materials, with indoor greenhouse hallways growing bananas in the desert. A kid favorite.","officialUrl":"https://www.earthship.com","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Earthship%20Visitor%20Center%20Taos%20NM","price":"~$8/person self-guided (est.)","photos":["assets/gulf-south/images/taos-nm/attr4-1.jpg","assets/gulf-south/images/taos-nm/attr4-2.jpg","assets/gulf-south/images/taos-nm/attr4-3.jpg","assets/gulf-south/images/taos-nm/attr4-4.jpg"]}],"restaurants":[{"name":"Orlando's New Mexican Cafe","detail":"Local favorite for classic New Mexican plates and strong margaritas on the patio.","price":"$"},{"name":"Michael's Kitchen","detail":"Taos institution — famous pastries, all-day breakfast, and New Mexican staples.","price":"$$"},{"name":"The Love Apple","detail":"Farm-to-table in a 200-year-old adobe chapel — the special-occasion dinner.","price":"$$$"}],"rainyDay":["Harwood Museum of Art","Taos Art Museum at the Fechin House","Millicent Rogers Museum (8 miles north)"],"driveNotes":"Taos is 70 miles north of Santa Fe via the Low Road (NM 68, 1.5 hours) or the scenic High Road (2.5 hours) — take one each way. At 7,000+ feet, altitude and sun are strong; hydrate and use sunscreen. Winter brings world-class skiing but also snow — carry chains. Taos Pueblo closes for tribal ceremonies some days; check ahead.","related":["santa-fe-nm","albuquerque-nm","carlsbad-nm"],"imageAsset":"assets/gulf-south/images/taos-nm/hero.jpg"},{"id":"carlsbad-nm","title":"Carlsbad, NM: Three-Day Caverns Adventure","destination":"Carlsbad, NM","state":"NM","stateName":"New Mexico","region":"Southeast New Mexico","days":3,"tripType":"caverns adventure","interests":["family","outdoors","nature","scenic"],"budget":650,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Descend into a cathedral of stone, then chase waterfalls and mountain sunsets.","overview":"Carlsbad Caverns is one of the great natural wonders of North America — a self-guided walk through rooms the size of football stadiums, 750 feet underground. Pair it with the Living Desert Zoo, a desert waterfall oasis, and a day trip into the Guadalupe Mountains, and three days in southeast New Mexico feel like an expedition. Book cavern entry times ahead. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["The Big Room — a single cave chamber 14 football fields large","The summer bat flight at dusk (May–October)","Sitting Bull Falls' desert waterfall oasis","Sunset from the Guadalupe Mountains' El Capitan","The Living Desert Zoo's mountain lions and prairie dogs"],"bestSeason":"March–May; September–November","familyFriendly":"Best for ages 5+. The Big Room trail is 1.25 miles of paved, stroller-friendly path; the Natural Entrance is steep — take the elevator down with little ones.","lat":32.17501,"lng":-104.44426,"itinerary":[{"day":1,"title":"The Big Room","morning":{"stop":"Carlsbad Caverns National Park","description":"Take the elevator 750 feet down and walk the 1.25-mile Big Room loop — a self-guided, paved trail through one of the world's largest cave chambers. Ranger talks at the formations run through the day.","cost":"Park entry ~$30 for adults; kids free (est.)","time":"9:00 AM – 1:00 PM"},"afternoon":{"stop":"Carlsbad Caverns National Park","description":"Walk down (or ride) the Natural Entrance trail for the full descent experience, then picnic at the amphitheater. The visitor center's exhibits and film round out the afternoon.","cost":"Included with entry (est.)","time":"1:30 PM – 4:30 PM"},"evening":{"stop":"Bat Flight Program","description":"In season (May–October), return at dusk for the ranger-led bat flight — hundreds of thousands of Brazilian free-tailed bats spiral out of the cave. Outside the season, catch the sunset from the visitor center overlook.","cost":"Free (est.)","time":"6:30 PM – 8:00 PM"}},{"day":2,"title":"Desert Zoo & Waterfall","morning":{"stop":"Living Desert Zoo & Gardens State Park","description":"Morning at this Chihuahuan Desert zoo: mountain lions, black bears, Mexican wolves, and prairie dogs along a 1.3-mile trail. Go early — the animals are most active before the heat.","cost":"Admission ~$35 for the family (est.)","time":"9:00 AM – 12:30 PM"},"afternoon":{"stop":"Sitting Bull Falls","description":"Drive 40 minutes into the Lincoln National Forest to this desert waterfall oasis — a 150-foot cascade into travertine pools. Swim, picnic, and hike the short canyon trail. The contrast with the desert is stunning.","cost":"Day-use ~$10/vehicle (est.)","time":"1:30 PM – 5:00 PM"},"evening":{"stop":"The Trinity Hotel Restaurant","description":"Dinner at Carlsbad's historic hotel restaurant — Italian-Southwestern cooking in a 1892 bank building. The patio on Canal Street is perfect for a warm evening.","cost":"Dinner ~$90 for the family (est.)","time":"6:30 PM – 8:30 PM"}},{"day":3,"title":"Guadalupe Mountains","morning":{"stop":"Guadalupe Mountains National Park","description":"Drive 45 minutes into Texas to the Salt Basin dunes and the El Capitan viewpoint. Hike the easy Smith Spring or Devil's Hall trailheads (check difficulty), and photograph the limestone reef cliffs.","cost":"Park entry $10/vehicle (est.)","time":"9:00 AM – 1:00 PM"},"afternoon":{"stop":"Guadalupe Mountains National Park","description":"Visit the Frijole Ranch museum and the spring-fed pond, then drive the scenic loop back. The fall colors (late October) in McKittrick Canyon are Texas's best-kept secret.","cost":"Included with entry (est.)","time":"1:30 PM – 4:30 PM"},"evening":{"stop":"YellowBrix Restaurant","description":"Farewell dinner in Carlsbad at this Southwestern favorite — green chile dishes, steaks, and a lively bar. The patio looks onto the Pecos River.","cost":"Dinner ~$85 for the family (est.)","time":"6:00 PM – 8:00 PM"}}],"attractions":[{"name":"Carlsbad Caverns National Park","description":"One of the world's great cave systems: the self-guided Big Room loop, the dramatic Natural Entrance, ranger-led tours, and the summer bat flight. 750 feet down, 56 degrees year-round.","officialUrl":"https://www.nps.gov/cave","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Carlsbad%20Caverns%20National%20Park%20Carlsbad%20NM","price":"$15/adult; kids 15 & under free (est.)","photos":["assets/gulf-south/images/carlsbad-nm/attr1-1.jpg","assets/gulf-south/images/carlsbad-nm/attr1-2.jpg","assets/gulf-south/images/carlsbad-nm/attr1-3.jpg","assets/gulf-south/images/carlsbad-nm/attr1-4.jpg"]},{"name":"Living Desert Zoo & Gardens State Park","description":"A Chihuahuan Desert zoo and botanical garden with mountain lions, black bears, Mexican wolves, and prairie dogs on a 1.3-mile trail. The desert plant collections are superb.","officialUrl":"https://www.livingdesertnm.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Living%20Desert%20Zoo%20Gardens%20Carlsbad%20NM","price":"~$10/adult, $7/child (est.)","photos":["assets/gulf-south/images/carlsbad-nm/attr2-1.jpg","assets/gulf-south/images/carlsbad-nm/attr2-2.jpg","assets/gulf-south/images/carlsbad-nm/attr2-3.jpg","assets/gulf-south/images/carlsbad-nm/attr2-4.jpg"]},{"name":"Sitting Bull Falls","description":"A 150-foot waterfall pouring into travertine pools in the Lincoln National Forest — a true desert oasis 40 minutes from Carlsbad. Swim, picnic, and hike the canyon trail.","officialUrl":"https://www.fs.usda.gov/lincoln","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Sitting%20Bull%20Falls%20Carlsbad%20NM","price":"~$10/vehicle day-use (est.)","photos":["assets/gulf-south/images/carlsbad-nm/attr3-1.jpg","assets/gulf-south/images/carlsbad-nm/attr3-2.jpg","assets/gulf-south/images/carlsbad-nm/attr3-3.jpg","assets/gulf-south/images/carlsbad-nm/attr3-4.jpg"]},{"name":"Guadalupe Mountains National Park","description":"Texas's rooftop — the ancient Capitan Reef's limestone cliffs, El Capitan, the Salt Basin dunes, and McKittrick Canyon's fall colors. A 45-minute drive from Carlsbad into a different world.","officialUrl":"https://www.nps.gov/gumo","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Guadalupe%20Mountains%20National%20Park%20Texas","price":"$10/vehicle (est.)","photos":["assets/gulf-south/images/carlsbad-nm/attr4-1.jpg","assets/gulf-south/images/carlsbad-nm/attr4-2.jpg","assets/gulf-south/images/carlsbad-nm/attr4-3.jpg","assets/gulf-south/images/carlsbad-nm/attr4-4.jpg"]}],"restaurants":[{"name":"The Trinity Hotel Restaurant","detail":"Historic 1892 bank building serving Italian-Southwestern cooking on Canal Street.","price":"$$"},{"name":"YellowBrix Restaurant","detail":"Southwestern favorite — green chile dishes, steaks, and a lively bar by the Pecos River.","price":"$$"},{"name":"Blue House Bakery and Cafe","detail":"Beloved breakfast and lunch spot — pastries, green chile breakfast burritos, friendly service.","price":"$"}],"rainyDay":["Carlsbad Caverns — the cave is 56 degrees and dry, rain or shine","Carlsbad Museum & Art Center downtown","The Trinity Hotel's historic lobby and shops"],"driveNotes":"Carlsbad is remote — 2.5 hours from El Paso, 4.5 from Albuquerque. The caverns are 20 miles southwest of town; Sitting Bull Falls is 40 minutes northwest; the Guadalupe Mountains are 45 minutes south into Texas. Fill gas in Carlsbad — stations are sparse. Book cavern entry times online well ahead, especially spring break and summer.","related":["white-sands-nm","taos-nm","big-bend-tx"],"imageAsset":"assets/gulf-south/images/carlsbad-nm/hero.jpg"},{"id":"white-sands-nm","title":"White Sands, NM: Two-Day Dunes Adventure","destination":"White Sands, NM","state":"NM","stateName":"New Mexico","region":"Southern New Mexico","days":2,"tripType":"dunes adventure","interests":["family","outdoors","nature","scenic"],"budget":450,"budgetNote":"For 2 adults + 2 kids: admissions, meals, and parking; lodging not included.","tagline":"Sled the whitest dunes on Earth, then touch space history next door.","overview":"White Sands is pure wonder: 275 square miles of wave-like gypsum dunes, the world's largest gypsum dunefield, where kids sled down slopes and sunsets turn the sand pink. Base in Alamogordo, add the space history museum and a small-town zoo, and two days feel like another planet. Go in the cool morning or at sunset — midday summer heat is fierce. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","highlights":["Sledding down gypsum dunes (buy sleds at the visitor center)","Sunset turning the dunes pink and gold","The full-moon night programs (reserve far ahead)","The space museum's rockets and the Clyde Tombaugh IMAX","Alameda Park Zoo's meerkats — one of America's oldest zoos"],"bestSeason":"October–April","familyFriendly":"Best for ages 4+. Dune sledding suits all ages; the sand is cool in the morning — go early. No shade in the dunes, so bring water and hats.","lat":32.77965,"lng":-106.1732,"itinerary":[{"day":1,"title":"The Dunes","morning":{"stop":"White Sands National Park","description":"Enter at opening and drive Dunes Drive to the Alkali Flat trailhead. Buy waxed sleds at the visitor center, then sled the big bowls near the loop — the gypsum is cool and soft in the morning.","cost":"Park entry $25/vehicle; sleds ~$25 each (est.)","time":"8:30 AM – 12:30 PM"},"afternoon":{"stop":"White Sands National Park","description":"Picnic at the covered shelters, walk the Interdune Boardwalk (stroller-friendly, great for kids), and cool off back in Alamogordo during the midday heat. Return for the evening ranger program if offered.","cost":"Included with entry (est.)","time":"1:00 PM – 4:00 PM"},"evening":{"stop":"White Sands National Park","description":"Drive back in for sunset — the dunes glow pink and gold, and photographers line the ridges. Stay for stargazing if the sky is clear; the Milky Way over the dunes is unreal.","cost":"Included with entry (est.)","time":"6:00 PM – 8:30 PM"}},{"day":2,"title":"Space & Zoo","morning":{"stop":"New Mexico Museum of Space History","description":"Tour the five-story museum on the Alamogordo hillside: rockets on the lawn, the International Space Hall of Fame, and the Clyde Tombaugh IMAX theater. The Daisy Track and space suits fascinate kids.","cost":"Admission ~$28 for the family (est.)","time":"10:00 AM – 1:00 PM"},"afternoon":{"stop":"Alameda Park Zoo","description":"One of North America's oldest zoos (1898) — small, shady, and perfect for an afternoon: meerkats, mountain lions, and the Education Center. The adjacent park has playgrounds and a splash pad.","cost":"Admission ~$16 for the family (est.)","time":"2:00 PM – 4:30 PM"},"evening":{"stop":"Hi-D-Ho Drive In","description":"Dinner at this classic drive-in — the Tiger Burger and green chile cheeseburger are local legends, delivered to your car. The retro neon is half the fun.","cost":"Dinner ~$40 for the family (est.)","time":"6:00 PM – 7:30 PM"}}],"attractions":[{"name":"White Sands National Park","description":"The world's largest gypsum dunefield — 275 square miles of wave-like white dunes. Sled the slopes, walk the boardwalk, catch the sunset ranger programs, and stargaze under some of America's darkest skies.","officialUrl":"https://www.nps.gov/whsa","mapsUrl":"https://www.google.com/maps/search/?api=1&query=White%20Sands%20National%20Park%20NM","price":"$25/vehicle (est.)","photos":["assets/gulf-south/images/white-sands-nm/attr1-1.jpg","assets/gulf-south/images/white-sands-nm/attr1-2.jpg","assets/gulf-south/images/white-sands-nm/attr1-3.jpg","assets/gulf-south/images/white-sands-nm/attr1-4.jpg"]},{"name":"New Mexico Museum of Space History","description":"The International Space Hall of Fame on the Alamogordo hillside: rockets on the lawn, five floors of space artifacts, the Daisy Track, and the Clyde Tombaugh IMAX. The view alone is worth the drive up.","officialUrl":"https://www.nmspacemuseum.org","mapsUrl":"https://www.google.com/maps/search/?api=1&query=New%20Mexico%20Museum%20of%20Space%20History%20Alamogordo%20NM","price":"~$8/adult, $6/child (est.)","photos":["assets/gulf-south/images/white-sands-nm/attr2-1.jpg","assets/gulf-south/images/white-sands-nm/attr2-2.jpg","assets/gulf-south/images/white-sands-nm/attr2-3.jpg","assets/gulf-south/images/white-sands-nm/attr2-4.jpg"]},{"name":"Alameda Park Zoo","description":"One of the oldest zoos in the Southwest (1898), set in shady Alameda Park: meerkats, mountain lions, alligators, and an education center. Small, affordable, and a local treasure.","officialUrl":"https://www.ci.alamogordo.nm.us/477/Alameda-Park-Zoo","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Alameda%20Park%20Zoo%20Alamogordo%20NM","price":"~$5/adult, $3/child (est.)","photos":["assets/gulf-south/images/white-sands-nm/attr3-1.jpg","assets/gulf-south/images/white-sands-nm/attr3-2.jpg","assets/gulf-south/images/white-sands-nm/attr3-3.jpg","assets/gulf-south/images/white-sands-nm/attr3-4.jpg"]},{"name":"Oliver Lee Memorial State Park","description":"A desert-mountain park at the foot of the Sacramentos: the Dog Canyon trail into a dramatic box canyon, a historic ranch house museum, and dark-sky stargazing. The riparian canyon is a hidden gem.","officialUrl":"https://www.emnrd.nm.gov/spd/oliver-lee-memorial-state-park/","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Oliver%20Lee%20Memorial%20State%20Park%20Alamogordo%20NM","price":"~$10/vehicle day-use (est.)","photos":["assets/gulf-south/images/white-sands-nm/attr4-1.jpg","assets/gulf-south/images/white-sands-nm/attr4-2.jpg","assets/gulf-south/images/white-sands-nm/attr4-3.jpg","assets/gulf-south/images/white-sands-nm/attr4-4.jpg"]}],"restaurants":[{"name":"Hi-D-Ho Drive In","detail":"Classic 50s drive-in — the Tiger Burger and green chile cheeseburger, delivered to your car.","price":"$"},{"name":"D. H. Lescombes Winery & Bistro","detail":"Winery bistro with New Mexican-Italian cooking and sunset views over the valley.","price":"$$"},{"name":"CJ's Si Señor","detail":"Local favorite for authentic New Mexican and Mexican plates — generous and family-friendly.","price":"$$"}],"rainyDay":["New Mexico Museum of Space History + IMAX","Alamogordo's Flickinger Center for a show","White Sands' visitor center exhibits (the dunes in rain are magical)"],"driveNotes":"White Sands is 15 minutes southwest of Alamogordo on US-70 — but the highway closes for missile tests from White Sands Missile Range, sometimes for hours; check the park's alerts before you go. Summer heat is extreme — visit October–April. Alamogordo is 1.5 hours from Las Cruces and 3.5 from Albuquerque.","related":["carlsbad-nm","albuquerque-nm","big-bend-tx"],"imageAsset":"assets/gulf-south/images/white-sands-nm/hero.jpg"}];
